// GENERATED by scripts/build-index.js from the subject files in this folder. Do not edit; run: node scripts/build-index.js
StudyData.addIndex(12, {"accountancy":{"syllabus":{"board":"CBSE","match":"textbook","books":["Accountancy Part I","Accountancy Part II"],"reviewed":false},"chapters":[{"id":"partnership-fundamentals","title":"Accounting for Partnership Firms – Fundamentals","section":"Partnership Accounts","summary":"Nature of partnership, the partnership deed and the rules that apply when there is no deed, fixed and fluctuating capital accounts, the profit and loss appropriation account, interest on capital and drawings, guarantee of profit and past adjustments.","nTerms":6},{"id":"goodwill-nature-and-valuation","title":"Goodwill: Nature and Valuation","section":"Partnership Accounts","summary":"Meaning and nature of goodwill, factors affecting its value, the need to value it in a partnership, and the average profit, super profit and capitalisation methods of valuation.","nTerms":6},{"id":"change-in-profit-sharing-ratio","title":"Change in Profit Sharing Ratio among Existing Partners","section":"Partnership Accounts","summary":"What happens when existing partners change their profit sharing ratio: sacrificing and gaining ratios, treatment of goodwill, reserves and accumulated profits or losses, and revaluation of assets and liabilities.","nTerms":6},{"id":"admission-of-a-partner","title":"Admission of a Partner","section":"Partnership Accounts","summary":"Accounting on the admission of a new partner: new and sacrificing ratios, premium for goodwill under AS 26, hidden goodwill, revaluation, reserves, and adjustment of capitals.","nTerms":6},{"id":"retirement-and-death-of-a-partner","title":"Retirement and Death of a Partner","section":"Partnership Accounts","summary":"Settling the account of a retiring or deceased partner: new and gaining ratios, goodwill, revaluation, reserves, the deceased partner's share of profit till death, and payment to the retiring partner or the executors.","nTerms":5},{"id":"dissolution-of-partnership-firm","title":"Dissolution of Partnership Firm","section":"Partnership Accounts","summary":"Dissolution of partnership versus dissolution of the firm, modes of dissolution, settlement of accounts under Section 48, and recording dissolution through the realisation account, partners' capital accounts and bank account.","nTerms":6},{"id":"accounting-for-share-capital","title":"Accounting for Share Capital","section":"Company Accounts","summary":"Features of a company, categories of share capital, kinds of shares, issue of shares at par and at a premium, over-subscription and pro-rata allotment, calls in arrears and in advance, and forfeiture and reissue of shares.","nTerms":6},{"id":"issue-and-redemption-of-debentures","title":"Issue and Redemption of Debentures","section":"Company Accounts","summary":"Meaning and types of debentures, issue at par, premium and discount, issue to vendors, terms of redemption and loss on issue, debentures as collateral security, interest on debentures, and an outline of redemption.","nTerms":6},{"id":"financial-statements-of-a-company","title":"Financial Statements of a Company","section":"Analysis of Financial Statements","summary":"Meaning, nature, objectives and limitations of financial statements, and the format of a company's balance sheet and statement of profit and loss as per Schedule III of the Companies Act, 2013.","nTerms":6},{"id":"analysis-of-financial-statements","title":"Analysis of Financial Statements","section":"Analysis of Financial Statements","summary":"Meaning, significance, objectives and limitations of analysing financial statements, and its tools, with comparative and common-size statements in detail.","nTerms":6},{"id":"accounting-ratios","title":"Accounting Ratios","section":"Analysis of Financial Statements","summary":"Meaning, objectives, advantages and limitations of ratio analysis, and the calculation of liquidity, solvency, activity (turnover) and profitability ratios, with the effect of transactions on ratios.","nTerms":6},{"id":"cash-flow-statement","title":"Cash Flow Statement","section":"Analysis of Financial Statements","summary":"Preparing a cash flow statement as per AS 3 (Revised): cash and cash equivalents, classification into operating, investing and financing activities, and cash flow from operating activities by the indirect method.","nTerms":6}]},"biology":{"syllabus":{"board":"CBSE","match":"textbook","books":["Biology"],"reviewed":false},"chapters":[{"id":"sexual-reproduction-in-flowering-plants","title":"Sexual Reproduction in Flowering Plants","section":"Reproduction","summary":"Flowers are the sites of sexual reproduction in angiosperms. This chapter follows the formation of pollen grains and embryo sac, pollination, double fertilisation, and the development of endosperm, embryo, seed and fruit.","nTerms":6},{"id":"human-reproduction","title":"Human Reproduction","section":"Reproduction","summary":"Humans are sexually reproducing and viviparous. This chapter covers the male and female reproductive systems, gametogenesis, the menstrual cycle, fertilisation, implantation, pregnancy, parturition and lactation.","nTerms":6},{"id":"reproductive-health","title":"Reproductive Health","section":"Reproduction","summary":"Reproductive health means total well-being in all aspects of reproduction. This chapter covers family planning, contraceptive methods, MTP, sexually transmitted infections, infertility and assisted reproductive technologies.","nTerms":6},{"id":"principles-of-inheritance-and-variation","title":"Principles of Inheritance and Variation","section":"Genetics and Evolution","summary":"Genetics explains how traits pass from parents to offspring. This chapter covers Mendel's laws and their extensions, the chromosomal theory, linkage, sex determination and Mendelian and chromosomal disorders.","nTerms":6},{"id":"molecular-basis-of-inheritance","title":"Molecular Basis of Inheritance","section":"Genetics and Evolution","summary":"DNA is the genetic material in most organisms. This chapter covers the experiments that proved it, DNA structure and packaging, replication, transcription, the genetic code, translation, the lac operon and the Human Genome Project.","nTerms":6},{"id":"evolution","title":"Evolution","section":"Genetics and Evolution","summary":"Evolution is the gradual change of living forms over time. This chapter covers the origin of life, evidence for evolution, Darwinian theory and natural selection, Hardy–Weinberg principle and human evolution.","nTerms":6},{"id":"human-health-and-disease","title":"Human Health and Disease","section":"Biology and Human Welfare","summary":"Health is more than the absence of disease. This chapter covers common infectious diseases, the immune system, vaccination, allergy and autoimmunity, AIDS, cancer, and drug and alcohol abuse.","nTerms":6},{"id":"microbes-in-human-welfare","title":"Microbes in Human Welfare","section":"Biology and Human Welfare","summary":"Microbes are used in food, industry, sewage treatment, energy and agriculture. This chapter covers fermented foods, antibiotics and other industrial products, sewage treatment, biogas, biocontrol agents and biofertilisers.","nTerms":6},{"id":"biotechnology-principles-and-processes","title":"Biotechnology: Principles and Processes","section":"Biotechnology","summary":"Biotechnology rests on genetic engineering and bioprocess engineering. This chapter covers the tools of recombinant DNA technology, vectors, PCR, transformation of host cells and bioreactors.","nTerms":6},{"id":"biotechnology-and-its-applications","title":"Biotechnology and its Applications","section":"Biotechnology","summary":"Biotechnology is applied in agriculture, medicine and animal research. This chapter covers GM crops such as Bt cotton, RNA interference, recombinant insulin, gene therapy, molecular diagnosis, transgenic animals and ethical issues such as biopiracy.","nTerms":6},{"id":"organisms-and-populations","title":"Organisms and Populations","section":"Ecology","summary":"Ecology studies the interactions of organisms with their environment. This chapter covers abiotic factors and adaptations, population attributes and growth models, and population interactions.","nTerms":6},{"id":"ecosystem","title":"Ecosystem","section":"Ecology","summary":"An ecosystem is a functional unit of nature. This chapter covers productivity, decomposition, energy flow and the 10 per cent law, ecological pyramids, succession, nutrient cycling and ecosystem services.","nTerms":6},{"id":"biodiversity-and-conservation","title":"Biodiversity and Conservation","section":"Ecology","summary":"Biodiversity is the variety of life at all levels. This chapter covers its levels and patterns, the species-area relationship, causes of loss, and in situ and ex situ conservation.","nTerms":6}]},"business":{"syllabus":{"board":"CBSE","match":"textbook","books":["Business Studies Part I","Business Studies Part II"],"reviewed":false},"chapters":[{"id":"nature-and-significance-of-management","title":"Nature and Significance of Management","section":"Principles and Functions of Management","summary":"What management is, effectiveness versus efficiency, its characteristics, objectives and importance, whether it is an art, a science or a profession, the levels and functions of management, and coordination as the essence of management.","nTerms":6},{"id":"principles-of-management","title":"Principles of Management","section":"Principles and Functions of Management","summary":"The nature and significance of management principles, F.W. Taylor's scientific management (principles and techniques) and Henri Fayol's 14 principles of general management, with a comparison of the two.","nTerms":6},{"id":"business-environment","title":"Business Environment","section":"Principles and Functions of Management","summary":"The meaning, features and importance of the business environment, its dimensions (economic, social, technological, political, legal), the New Economic Policy of 1991 (liberalisation, privatisation, globalisation), its impact on business, and demonetisation.","nTerms":6},{"id":"planning","title":"Planning","section":"Principles and Functions of Management","summary":"Planning means deciding in advance what to do and how to do it. This chapter covers its importance, features and limitations, the planning process, and the types of plans: objectives, strategy, policy, procedure, method, rule, programme and budget.","nTerms":6},{"id":"organising","title":"Organising","section":"Principles and Functions of Management","summary":"How work, people and authority are arranged to carry out plans: the organising process, its importance, functional and divisional structures, formal and informal organisation, delegation and decentralisation.","nTerms":6},{"id":"staffing","title":"Staffing","section":"Principles and Functions of Management","summary":"Filling and keeping filled the positions in an organisation: the importance and process of staffing, sources of recruitment, the selection process, and training and development methods.","nTerms":6},{"id":"directing","title":"Directing","section":"Principles and Functions of Management","summary":"Directing means instructing, guiding, communicating with and inspiring people. This chapter covers its features and importance, and its four elements: supervision, motivation (Maslow's hierarchy and incentives), leadership styles and communication (networks and barriers).","nTerms":6},{"id":"controlling","title":"Controlling","section":"Principles and Functions of Management","summary":"Controlling ensures that activities follow plans. This chapter covers its importance and limitations, its relationship with planning, the steps in the controlling process, critical point control, management by exception, and corrective actions.","nTerms":6},{"id":"financial-management","title":"Financial Management","section":"Business Finance and Marketing","summary":"Optimal procurement and use of finance: the objective of wealth maximisation, the three financial decisions (investment, financing and dividend) and their factors, financial planning, capital structure and trading on equity, and the factors affecting fixed and working capital.","nTerms":6},{"id":"financial-markets","title":"Financial Markets","section":"Business Finance and Marketing","summary":"Markets for creating and exchanging financial assets: functions of financial markets, money market instruments, the capital market (primary and secondary), stock exchanges and the role of SEBI.","nTerms":6},{"id":"marketing","title":"Marketing","section":"Business Finance and Marketing","summary":"The concept and functions of marketing, the marketing philosophies, and the marketing mix (4 Ps): product (branding, packaging, labelling), price, place (channels and physical distribution) and promotion (advertising, personal selling, sales promotion, public relations).","nTerms":6},{"id":"consumer-protection","title":"Consumer Protection","section":"Business Finance and Marketing","summary":"Why consumers need protection, the Consumer Protection Act, 2019, the rights and responsibilities of consumers, who can file a complaint, the three-tier redressal machinery, the reliefs available, and the role of consumer organisations.","nTerms":6}]},"chemistry":{"syllabus":{"board":"CBSE","match":"textbook","books":["Chemistry Part I","Chemistry Part II"],"reviewed":false},"chapters":[{"id":"solutions","title":"Solutions","section":"Physical Chemistry","summary":"Types of solutions and ways of expressing concentration, solubility of gases (Henry's law), vapour pressure and Raoult's law, ideal and non-ideal solutions, colligative properties and their use in finding molar masses, and the van't Hoff factor.","nTerms":6},{"id":"electrochemistry","title":"Electrochemistry","section":"Physical Chemistry","summary":"Conversion between chemical and electrical energy: galvanic cells and electrode potentials, the Nernst equation, cell emf and Gibbs energy, conductance of electrolytic solutions and Kohlrausch's law, electrolysis and Faraday's laws, batteries, fuel cells and corrosion.","nTerms":6},{"id":"chemical-kinetics","title":"Chemical Kinetics","section":"Physical Chemistry","summary":"How fast reactions go: rate of reaction, rate law, order and molecularity, integrated rate equations and half-lives of zero- and first-order reactions, pseudo first-order reactions, the Arrhenius equation and collision theory.","nTerms":6},{"id":"d-and-f-block-elements","title":"The d- and f-Block Elements","section":"Inorganic Chemistry","summary":"Transition elements and inner transition elements: electronic configuration, general trends in the first transition series (oxidation states, magnetic behaviour, colour, catalysis, interstitial compounds, alloys), potassium dichromate and permanganate, lanthanoids and actinoids.","nTerms":6},{"id":"coordination-compounds","title":"Coordination Compounds","section":"Inorganic Chemistry","summary":"Werner's theory, ligands, coordination number and IUPAC naming of coordination compounds, structural and stereo-isomerism, bonding by valence bond theory and crystal field theory, colour and magnetic properties, and uses of complexes.","nTerms":6},{"id":"haloalkanes-and-haloarenes","title":"Haloalkanes and Haloarenes","section":"Organic Chemistry","summary":"Classification, naming and preparation of alkyl and aryl halides, the nature of the C–X bond, SN1 and SN2 mechanisms with their stereochemistry, elimination and reactions with metals, and why haloarenes behave differently from haloalkanes.","nTerms":6},{"id":"alcohols-phenols-and-ethers","title":"Alcohols, Phenols and Ethers","section":"Organic Chemistry","summary":"Naming, preparation and properties of alcohols, phenols and ethers: acidity, reactions of the O–H and C–O bonds, distinguishing tests, electrophilic substitution in phenol, named reactions (Kolbe, Reimer–Tiemann, Williamson) and cleavage of ethers.","nTerms":6},{"id":"aldehydes-ketones-and-carboxylic-acids","title":"Aldehydes, Ketones and Carboxylic Acids","section":"Organic Chemistry","summary":"Carbonyl compounds and carboxylic acids: naming, preparation by named reactions, nucleophilic addition, reduction and oxidation, tests for aldehydes, aldol and Cannizzaro reactions, acidity of carboxylic acids and their characteristic reactions.","nTerms":6},{"id":"amines","title":"Amines","section":"Organic Chemistry","summary":"Classification, naming and preparation of amines, their basic character, important reactions and tests (carbylamine, Hinsberg), electrophilic substitution in aniline, and the preparation and uses of diazonium salts.","nTerms":6},{"id":"biomolecules","title":"Biomolecules","section":"Organic Chemistry","summary":"The chemistry of life's molecules: classification and structure of carbohydrates (glucose, fructose, disaccharides, polysaccharides), amino acids and proteins, enzymes, vitamins and nucleic acids.","nTerms":6}]},"economics":{"syllabus":{"board":"CBSE","match":"textbook","books":["Introductory Macroeconomics","Indian Economic Development"],"note":"Arranged as CBSE examines it in Class 12.","reviewed":false},"chapters":[{"id":"macro-introduction","title":"Introduction to Macroeconomics","section":"Introductory Macroeconomics","summary":"What macroeconomics studies, why it emerged as a separate subject after the Great Depression and Keynes's General Theory, and the features and sectors of a capitalist economy.","nTerms":6},{"id":"national-income-accounting","title":"National Income Accounting","section":"Introductory Macroeconomics","summary":"Basic concepts (final and intermediate goods, stocks and flows, investment and depreciation), the circular flow of income, the three methods of measuring GDP, related aggregates (GNP, NNP, national income, personal income), real vs nominal GDP, and why GDP is not a perfect measure of welfare.","nTerms":6},{"id":"money-and-banking","title":"Money and Banking","section":"Introductory Macroeconomics","summary":"Barter and the functions of money, the measures of money supply (M1 to M4), how commercial banks create money (money multiplier), and the functions of the Reserve Bank of India and its tools of monetary policy.","nTerms":6},{"id":"determination-of-income-and-employment","title":"Determination of Income and Employment","section":"Introductory Macroeconomics","summary":"How equilibrium income is determined in the short run by aggregate demand: the consumption and saving functions, propensities to consume and save, equilibrium (AD = AS, S = I), the investment multiplier, and the problems of excess and deficient demand.","nTerms":6},{"id":"government-budget-and-the-economy","title":"Government Budget and the Economy","section":"Introductory Macroeconomics","summary":"What a government budget is, its objectives (allocation, redistribution, stabilisation), how receipts and expenditures are classified into revenue and capital accounts, and the measures of government deficit: revenue, fiscal and primary deficit.","nTerms":6},{"id":"open-economy-macroeconomics","title":"Open Economy Macroeconomics","section":"Introductory Macroeconomics","summary":"How an open economy is linked to the rest of the world, the balance of payments (current and capital accounts, surplus and deficit), the foreign exchange market, and fixed, flexible and managed floating exchange rate systems.","nTerms":6},{"id":"indian-economy-on-the-eve-of-independence","title":"Indian Economy on the Eve of Independence","section":"Indian Economic Development","summary":"The state of India's economy in 1947 after nearly two centuries of British rule: very slow growth, stagnant agriculture, decline of handicrafts, a trade pattern that drained wealth, poor health and literacy, a lopsided occupational structure and infrastructure built for colonial needs.","nTerms":6},{"id":"indian-economy-1950-1990","title":"Indian Economy 1950–1990","section":"Indian Economic Development","summary":"How independent India chose a mixed economy and five year planning, the goals of the plans, land reforms and the Green Revolution in agriculture, and the industrial and trade policies (IPR 1956, licensing, small-scale industry, import substitution), with an appraisal of their results.","nTerms":6},{"id":"liberalisation-privatisation-globalisation","title":"Liberalisation, Privatisation and Globalisation: An Appraisal","section":"Indian Economic Development","summary":"Why India launched the New Economic Policy in 1991, the main reforms under liberalisation, privatisation and globalisation (industry, finance, taxes, foreign exchange, trade; disinvestment; outsourcing; WTO), and an appraisal of their results.","nTerms":6},{"id":"human-capital-formation","title":"Human Capital Formation in India","section":"Indian Economic Development","summary":"What human capital is and how it is built through education, health, on-the-job training, migration and information; how it differs from physical capital and from human development; and the growth and problems of India's education sector.","nTerms":6},{"id":"rural-development","title":"Rural Development","section":"Indian Economic Development","summary":"Why rural development matters and its key issues: rural credit (banks, NABARD, Self-Help Groups), agricultural marketing and alternative channels, diversification into livestock, fisheries and horticulture, and sustainable development through organic farming.","nTerms":6},{"id":"employment-growth-informalisation","title":"Employment: Growth, Informalisation and Other Issues","section":"Indian Economic Development","summary":"Who is a worker, how India's workforce is distributed (rural and urban, men and women, self-employed and hired, by sector), jobless growth, informalisation, types of unemployment and the government's role in creating jobs.","nTerms":6},{"id":"environment-and-sustainable-development","title":"Environment and Sustainable Development","section":"Indian Economic Development","summary":"The functions of the environment and why an environmental crisis arises, global warming and ozone depletion, the state of India's environment (land degradation, pollution), and the meaning of and strategies for sustainable development.","nTerms":6},{"id":"india-and-its-neighbours","title":"Comparative Development Experiences of India and its Neighbours","section":"Indian Economic Development","summary":"How India, Pakistan and China, which began their development journeys at about the same time, followed different strategies and reforms, and how they compare on growth, population and human development.","nTerms":6}]},"english":{"syllabus":{"board":"CBSE","match":"textbook","books":["Flamingo","Vistas"],"note":"Writing skills, plus every lesson of Flamingo and Vistas in the current NCERT books (summarised in our own words).","reviewed":false},"chapters":[{"id":"notice-writing","title":"Notice","section":"Writing Skills","summary":"Writing a short, boxed notice of about 50 words that informs readers about an event, meeting, change of schedule or lost-and-found item, with every key detail in the correct format.","nTerms":5},{"id":"invitation-and-reply","title":"Invitation and Reply","section":"Writing Skills","summary":"Writing a formal invitation (about 50 words) in the third person, and a reply that accepts or declines it, with all details of the occasion given clearly.","nTerms":5},{"id":"letter-to-the-editor","title":"Letter to the Editor","section":"Writing Skills","summary":"Writing a formal letter of about 120 words to a newspaper editor to express a view or draw attention to a public problem, in the correct format with a clear subject line.","nTerms":5},{"id":"job-application","title":"Job Application","section":"Writing Skills","summary":"Writing a formal job application letter of about 120 words in reply to an advertisement, with an enclosed bio-data or CV, giving qualifications and experience clearly and politely.","nTerms":5},{"id":"article-writing","title":"Article","section":"Writing Skills","summary":"Writing an article of about 120 to 150 words on a topic of social or personal interest, with an eye-catching title, a byline, a clear introduction, a developed body and a thoughtful conclusion.","nTerms":5},{"id":"report-writing","title":"Report","section":"Writing Skills","summary":"Writing a newspaper or school report of about 120 words on an event, in the past tense and passive voice, with a heading, a byline, and a factual body that answers the 5 Ws and 1 H.","nTerms":5},{"id":"the-last-lesson","title":"The Last Lesson","section":"Flamingo","summary":"A story by Alphonse Daudet, set in Alsace after a Prussian victory, in which a schoolboy named Franz attends the last French lesson ever taught in his village school and learns to value his language too late.","nTerms":5},{"id":"lost-spring","title":"Lost Spring","section":"Flamingo","summary":"Anees Jung's account of two sets of children robbed of their childhood by poverty: Saheb, a ragpicker boy from Bangladesh who lives in Seemapuri, Delhi, and Mukesh, who is born into the bangle-making families of Firozabad.","nTerms":5},{"id":"deep-water","title":"Deep Water","section":"Flamingo","summary":"William O. Douglas recalls how a childhood near-drowning left him with a deep fear of water, and how patient training and willpower finally helped him overcome that fear.","nTerms":5},{"id":"the-rattrap","title":"The Rattrap","section":"Flamingo","summary":"Selma Lagerlöf's story of a poor peddler who sells rattraps and sees the world as a big rattrap, until an act of kindness from an ironmaster's daughter awakens the goodness in him.","nTerms":5},{"id":"indigo","title":"Indigo","section":"Flamingo","summary":"Louis Fischer’s account of how Gandhi, at the request of a peasant named Rajkumar Shukla, went to Champaran in Bihar in 1917 and helped the poor indigo sharecroppers win relief from the landlords.","nTerms":5},{"id":"poets-and-pancakes","title":"Poets and Pancakes","section":"Flamingo","summary":"A humorous memoir by the Tamil writer Asokamitran about his years at Gemini Studios in Madras, covering its make-up room, its poets and its odd visitors, and ending with the mystery of an English poet's visit that is solved only years later.","nTerms":5},{"id":"the-interview","title":"The Interview","section":"Flamingo","summary":"In Part I, Christopher Silvester discusses what interviews are worth and why many famous people dislike them. Part II is an extract from Mukund Padmanabhan's interview with the Italian scholar and novelist Umberto Eco.","nTerms":5},{"id":"going-places","title":"Going Places","section":"Flamingo","summary":"A short story by A. R. Barton about Sophie, a schoolgirl from a poor family who dreams of owning a boutique and invents a meeting with the footballer Danny Casey. It explores adolescent fantasy and the gap between dreams and reality.","nTerms":5},{"id":"my-mother-at-sixty-six","title":"My Mother at Sixty-six","section":"Flamingo","summary":"Kamala Das’s poem about a car journey to the airport, during which the poet sees her ageing mother’s pale face, feels a childhood fear of losing her, and hides her anxiety behind a smile.","nTerms":5},{"id":"keeping-quiet","title":"Keeping Quiet","section":"Flamingo","summary":"Pablo Neruda’s poem asks people to keep still and silent for a moment, so that they may stop harming each other and the earth and understand themselves and the value of life.","nTerms":5},{"id":"a-thing-of-beauty","title":"A Thing of Beauty","section":"Flamingo","summary":"An opening passage from John Keats's long poem Endymion, praising beauty as a lasting joy that lifts us above sorrow, dullness and the lack of noble people.","nTerms":5},{"id":"a-roadside-stand","title":"A Roadside Stand","section":"Flamingo","summary":"Robert Frost's poem about poor rural people who set up a roadside stand hoping that passing city motorists will buy, while indifferent drivers pass by and well-meaning officials plan to ‘help’ them in ways that do them little good.","nTerms":5},{"id":"aunt-jennifers-tigers","title":"Aunt Jennifer’s Tigers","section":"Flamingo","summary":"Adrienne Rich’s poem about Aunt Jennifer, a woman oppressed in her marriage, who embroiders fearless tigers that express the freedom and strength she cannot have in her own life.","nTerms":5},{"id":"the-third-level","title":"The Third Level","section":"Vistas","summary":"Jack Finney’s fantasy about Charley, a New Yorker who finds a mysterious third level at Grand Central Station that leads to the peaceful America of 1894, and who longs to escape there from the pressures of modern life.","nTerms":5},{"id":"the-tiger-king","title":"The Tiger King","section":"Vistas","summary":"Kalki's satire about the Maharaja of Pratibandapuram, who is foretold to die by a tiger and sets out to kill a hundred of them, only to meet his end in a quite unexpected way.","nTerms":5},{"id":"journey-to-the-end-of-the-earth","title":"Journey to the End of the Earth","section":"Vistas","summary":"Tishani Doshi describes her expedition to Antarctica with the Students on Ice programme and shows how this frozen continent holds the record of Earth's past and warns of its future under climate change.","nTerms":5},{"id":"the-enemy","title":"The Enemy","section":"Vistas","summary":"Pearl S. Buck’s story set in Japan during a war, in which Dr Sadao Hoki, a surgeon, saves the life of a wounded American prisoner washed up on his beach, putting his duty as a doctor before his duty as a patriot.","nTerms":5},{"id":"on-the-face-of-it","title":"On the Face of It","section":"Vistas","summary":"Susan Hill’s one-act play about Derry, a lonely boy with a badly burnt face who hides from the world, and Mr Lamb, an old man with an artificial leg who tries to help him see life differently.","nTerms":5},{"id":"memories-of-childhood","title":"Memories of Childhood","section":"Vistas","summary":"Two autobiographical accounts of discrimination: Zitkala-Sa, a Native American girl, recalls the shock of having her long hair cut at a boarding school, and Bama, a Dalit woman from Tamil Nadu, recalls how she learnt about untouchability and was inspired to study.","nTerms":5}]},"englishpb":{"syllabus":{"board":"PSEB","match":"textbook","books":["A Rainbow of English (PSEB, Class 12)","English Grammar and Composition for XI and XII (PSEB)"],"note":"Follows the PSEB 2026–27 syllabus; lessons summarised in our own words from the PSEB textbook (2023–24 edition).","reviewed":false},"chapters":[{"id":"determiners","title":"Determiners","section":"Grammar","summary":"Determiners are words placed before a noun to show which one, how many or how much: articles, demonstratives, possessives, quantifiers and numbers.","nTerms":5},{"id":"non-finites","title":"Non-finites","section":"Grammar","summary":"Non-finite verb forms (infinitive, gerund and participle) do not show tense or person and do not act as the main verb of a sentence.","nTerms":5},{"id":"transformation-of-sentences","title":"Transformation of Sentences","section":"Grammar","summary":"Changing a sentence from one form to another without changing its meaning: simple, compound and complex; affirmative and negative; assertive, interrogative and exclamatory; degrees of comparison.","nTerms":5},{"id":"voice","title":"Voice","section":"Grammar","summary":"Voice shows whether the subject does the action (active) or receives it (passive). This chapter covers changing voice across tenses, modals, questions, commands and requests.","nTerms":5},{"id":"narration","title":"Narration","section":"Grammar","summary":"Narration (direct and indirect speech) is about reporting what someone said. This chapter covers the changes of tense, pronoun, time and place, and rules for statements, questions, commands and exclamations.","nTerms":5},{"id":"precis-writing","title":"Précis Writing","section":"Writing","summary":"A précis is a short, clear version of a passage in about one-third of its length, keeping the main ideas in the writer's order and in your own words.","nTerms":5},{"id":"letters-and-applications","title":"Letters and Applications","section":"Writing","summary":"Formats and tone for official letters, business letters, letters to the editor and school or office applications.","nTerms":5},{"id":"explaining-newspaper-headlines","title":"Explaining Newspaper Headlines","section":"Writing","summary":"Headlines are written in a compressed style. This chapter shows how to read them and expand each into a clear full sentence.","nTerms":5},{"id":"e-mail-writing","title":"E-mail Writing","section":"Writing","summary":"How to write a clear, polite e-mail with the correct fields, tone and structure, for formal and informal purposes.","nTerms":5},{"id":"translation-tips","title":"Translation Tips","section":"Writing","summary":"Practical rules for translating passages from Punjabi (or Hindi) into natural English: tenses, word order, idioms and common pitfalls.","nTerms":5},{"id":"hassans-attendance-problem","title":"Hassan's Attendance Problem","section":"Prose","summary":"Sudha Murthy, a teacher of computer applications, recalls Hassan, a gifted but irregular student who always begged for attendance and still scored first class. Years later he turns up as a door-to-door salesman, having drifted through jobs because of his lazy habits, and she urges him to start again.","nTerms":5},{"id":"the-march-king","title":"The March King","section":"Prose","summary":"A biographical sketch of John Philip Sousa, from the boy in Washington who vowed to be a musician to the bandmaster of the US Marine Band known as the March King. It shows how a boy who tried other careers returned to his true calling, music.","nTerms":5},{"id":"thinking-out-of-the-box-lateral-thinking","title":"Thinking Out of the Box: Lateral Thinking","section":"Prose","summary":"Adapted from an article on lateral thinking. Through the tale of a clever girl who defeats a cunning moneylender and a millionaire who 'parks' his car in a bank, the lesson shows that creative, unconventional thinking can solve problems that logic alone cannot.","nTerms":5},{"id":"on-saying-please","title":"On Saying 'Please'","section":"Prose","summary":"A. G. Gardiner begins with a lift-man who threw out a passenger for not saying 'please' and was fined. He argues that although bad manners are not a crime, they poison social life, and he praises a cheerful bus conductor who shows that courtesy lightens everyone's day.","nTerms":5},{"id":"the-story-of-my-life","title":"The Story of My Life","section":"Prose","summary":"An extract from Helen Keller's autobiography. She recalls 3 March 1887, the day her teacher Anne Sullivan arrived, and the day at the well-house when she suddenly grasped that everything has a name, which opened the world of language to her.","nTerms":5},{"id":"two-gentlemen-of-verona","title":"Two Gentlemen of Verona","section":"Prose","summary":"A. J. Cronin's story of two poor Italian boys, Nicola and Jacopo, who work at every odd job in Verona to pay the hospital fees of their sister Lucia, who has tuberculosis of the spine. The narrator discovers their secret and is deeply moved.","nTerms":5},{"id":"in-celebration-of-being-alive","title":"In Celebration of Being Alive","section":"Prose","summary":"Dr Christian Barnard, the heart-transplant pioneer, reflects on why people suffer. A hospital 'Grand Prix' run by a blind boy and a one-armed boy on a breakfast trolley teaches him that suffering does not ennoble us, but that life should be lived joyfully with what we have left.","nTerms":5},{"id":"ghadari-babas-in-kalapani-jail","title":"Ghadari Babas in Kalapani Jail","section":"Prose","summary":"An account by Dr Harish K. Puri of the Ghadar Party revolutionaries, mostly older men called Babas, who were sent to the Cellular Jail at Port Blair (Kala Pani). It describes the harsh treatment they faced and how their strikes and spirit forced some reforms.","nTerms":5},{"id":"prayer-of-the-woods","title":"Prayer of the Woods","section":"Poetry","summary":"In this short anonymous poem the woods speak in the first person, listing the many gifts trees give to humans, from warmth and shade to furniture and the coffin, and end with a plea to passers-by not to harm them.","nTerms":5},{"id":"on-friendship","title":"On Friendship","section":"Poetry","summary":"A prose-poem by Kahlil Gibran, from his book The Prophet, in which the speaker describes friendship as an answer to our needs and as a bond of deep, unselfish companionship.","nTerms":5},{"id":"the-echoing-green","title":"The Echoing Green","section":"Poetry","summary":"A poem by William Blake from Songs of Innocence that pictures a spring day on the village green, with children at play and old folk watching, until evening falls and the children rest.","nTerms":5},{"id":"once-upon-a-time","title":"Once Upon a Time","section":"Poetry","summary":"A poem by the Nigerian poet Gabriel Okara in which a father tells his son how people have learned to be false, wearing smiles and handshakes without feeling, and asks to be taught how to be sincere again.","nTerms":5},{"id":"father-returning-home","title":"Father Returning Home","section":"Poetry","summary":"Dilip Chitre's poem, from the collection Travelling in a Cage, pictures an ageing father travelling home on a late-evening Mumbai suburban train, lonely even in a crowd, cut off from his sullen children, and dreaming of ancestors and descendants.","nTerms":5},{"id":"the-road-not-taken","title":"The Road Not Taken","section":"Poetry","summary":"Robert Frost's well-known poem about a traveller who comes upon two paths in a wood, chooses one, and reflects that this choice has shaped his life.","nTerms":5},{"id":"on-his-blindness","title":"On His Blindness","section":"Poetry","summary":"A sonnet by John Milton in which the poet, who had lost his sight, wonders whether he can still serve God, and is answered by Patience that God needs no work or gift from man, only willing acceptance.","nTerms":5},{"id":"the-school-for-sympathy","title":"The School for Sympathy","section":"Extensive Study","summary":"E. V. Lucas visits Miss Beam's unusual school, where children learn sympathy by spending a day blind, lame, deaf, maimed or dumb. Led around by him, a blind-for-the-day girl shows how real the lesson is, and Miss Beam feels her system is justified.","nTerms":5},{"id":"a-chameleon","title":"A Chameleon","section":"Extensive Study","summary":"Anton Chekhov's satire in which a police superintendent, Otchumyelov, keeps changing his judgement of a puppy that bit a goldsmith's finger, depending on whether the dog turns out to belong to a powerful General or his brother.","nTerms":5},{"id":"bholi","title":"Bholi","section":"Extensive Study","summary":"K. A. Abbas tells of Sulekha, called Bholi, the simpleton, the neglected, pock-marked and stammering youngest child of a village numberdar. Sent to a new school, she gains confidence and at her wedding boldly rejects a greedy bridegroom.","nTerms":5},{"id":"the-gold-frame","title":"The Gold Frame","section":"Extensive Study","summary":"R. K. Laxman's humorous story of Datta, a silent frame-maker, who ruins a customer's cherished photograph of his late grandfather and secretly frames a lookalike. The customer's only complaint is that the mount is square rather than oval.","nTerms":5},{"id":"the-barbers-trade-union","title":"The Barber's Trade Union","section":"Extensive Study","summary":"Mulk Raj Anand recalls Chandu, the barber's son and his boyhood hero, who dresses like a doctor, is insulted by the high-caste elders, buys a bicycle, goes on strike and organises the barbers into one of the first trade unions.","nTerms":5},{"id":"the-bull-beneath-the-earth","title":"The Bull beneath the Earth","section":"Extensive Study","summary":"K. S. Virk's story of Mann Singh, a soldier on leave who visits his friend Karam Singh's village, and finds the family oddly cold. He later learns they have already received news of Karam Singh's death and are hiding their grief to spare him.","nTerms":5}]},"geography":{"syllabus":{"board":"CBSE","match":"textbook","books":["Fundamentals of Human Geography","India: People and Economy"],"reviewed":false},"chapters":[{"id":"human-geography-nature-and-scope","title":"Human Geography: Nature and Scope","section":"Fundamentals of Human Geography","summary":"What human geography studies, how humans and nature interact (determinism, possibilism, neo-determinism), how the subject's approaches changed over time, and its fields and sub-fields.","nTerms":6},{"id":"world-population","title":"The World Population: Distribution, Density and Growth","section":"Fundamentals of Human Geography","summary":"How the world's people are unevenly spread, the factors that affect distribution, how density and growth are measured, migration, the demographic transition theory and population control.","nTerms":6},{"id":"human-development","title":"Human Development","section":"Fundamentals of Human Geography","summary":"The difference between growth and development, the concept and four pillars of human development, the approaches to it, and how the Human Development Index measures it.","nTerms":6},{"id":"primary-activities","title":"Primary Activities","section":"Fundamentals of Human Geography","summary":"Activities that depend directly on the environment: hunting and gathering, pastoralism, the main types of agriculture around the world, and mining.","nTerms":6},{"id":"secondary-activities","title":"Secondary Activities","section":"Fundamentals of Human Geography","summary":"Manufacturing and its features, the factors that decide where industries are located, the classification of industries by size, inputs, output and ownership, and footloose and high-tech industries.","nTerms":6},{"id":"tertiary-and-quaternary-activities","title":"Tertiary and Quaternary Activities","section":"Fundamentals of Human Geography","summary":"Service activities: trade, transport, communication and services; tourism and medical tourism; and the knowledge-based quaternary and quinary activities, outsourcing and the digital divide.","nTerms":6},{"id":"world-transport-and-communication","title":"Transport and Communication","section":"Fundamentals of Human Geography","summary":"Modes of transport across the world: roads and trans-continental highways, trans-continental railways, major sea routes and shipping canals, inland waterways, air transport, pipelines, and communication.","nTerms":6},{"id":"world-international-trade","title":"International Trade","section":"Fundamentals of Human Geography","summary":"The history and bases of international trade, its important aspects including balance of trade, types of trade, free trade and the WTO, regional trade blocs, concerns about trade, and ports as gateways of trade.","nTerms":6},{"id":"india-population","title":"Population: Distribution, Density, Growth and Composition","section":"India: People and Economy","summary":"How India's population is distributed and how dense it is, the four phases of population growth since 1901, regional variations, adolescents, and the rural–urban, linguistic, religious and working composition of the population.","nTerms":6},{"id":"human-settlements","title":"Human Settlements","section":"India: People and Economy","summary":"Rural settlement types in India and the factors behind them, how urban areas are defined, the evolution of Indian towns, urbanisation, classification of towns by size, and the functional classification of Indian cities.","nTerms":6},{"id":"land-resources-and-agriculture","title":"Land Resources and Agriculture","section":"India: People and Economy","summary":"Land use categories and changes in India, common property resources, cropping seasons and types of farming, the major crops and where they grow, agricultural development since Independence, and the problems of Indian agriculture.","nTerms":6},{"id":"water-resources","title":"Water Resources","section":"India: People and Economy","summary":"Surface and ground water resources of India, how water is used in irrigation, industry and homes, the problems of scarcity and quality, and water conservation methods such as watershed management and rainwater harvesting.","nTerms":6},{"id":"mineral-and-energy-resources","title":"Mineral and Energy Resources","section":"India: People and Economy","summary":"Types of minerals and where they are found in India, the major mineral belts, conventional energy sources (coal, petroleum, natural gas, electricity) and non-conventional sources (solar, wind, tidal, biogas, geothermal), and why conservation matters.","nTerms":6},{"id":"planning-and-sustainable-development","title":"Planning and Sustainable Development in Indian Context","section":"India: People and Economy","summary":"What planning is, the target area and target group approaches, case studies of the Indira Gandhi Canal and Bharmaur tribal area, and the idea of sustainable development.","nTerms":6},{"id":"india-transport-and-communication","title":"Transport and Communication","section":"India: People and Economy","summary":"India's road, rail, water, air and pipeline transport networks, major ports, and the growth of communication through telecom, mass media and satellites.","nTerms":6},{"id":"india-international-trade","title":"International Trade","section":"India: People and Economy","summary":"The changing composition, direction and policy of India's foreign trade, major exports and imports, the balance of trade, and ports and airports as gateways of trade.","nTerms":6},{"id":"selected-issues-and-problems","title":"Geographical Perspective on Selected Issues and Problems","section":"India: People and Economy","summary":"A geographical look at environmental pollution (air, water and solid waste), urban problems including slums, and land degradation, with their causes and remedies.","nTerms":6}]},"hindi":{"syllabus":{"board":"CBSE","match":"textbook","books":["Aroh Bhag 2","Vitan Bhag 2"],"note":"Every lesson of Aroh Bhag 2 and Vitan Bhag 2 (summarised in our own words), plus the writing chapters from Abhivyakti aur Madhyam.","reviewed":false},"chapters":[{"id":"aatm-parichay-ek-geet","title":"आत्म-परिचय, एक गीत","section":"आरोह","summary":"हरिवंश राय बच्चन की 'आत्म-परिचय' कविता में कवि और संसार के प्रेम-विरोध भरे संबंध का चित्रण है, जबकि 'एक गीत' (दिन जल्दी-जल्दी ढलता है) में समय की गतिशीलता और प्रिय की प्रतीक्षा से जीवन में आने वाली गति व अकेलेपन की पीड़ा व्यक्त हुई है।","nTerms":6},{"id":"patang","title":"पतंग","section":"आरोह","summary":"आलोक धन्वा की लंबी कविता 'पतंग' के तीसरे भाग में भादो के बीतने और शरद ऋतु के आने का उल्लास है। पतंग के बहाने बच्चों की उमंग, निडरता और ऊँचाइयों को छूने की चाह का सुंदर बिंबों में चित्रण हुआ है।","nTerms":6},{"id":"kavita-ke-bahane-baat-sidhi-thi-par","title":"कविता के बहाने, बात सीधी थी पर","section":"आरोह","summary":"कुँवर नारायण की 'कविता के बहाने' में कविता की उड़ान, खिलने और खेल जैसे असीम स्वभाव को चिड़िया, फूल और बच्चे के बहाने समझाया गया है। 'बात सीधी थी पर' में कथ्य और भाषा के द्वंद्व के सहारे बताया गया है कि भाषा को सहजता से बरतना ज़रूरी है।","nTerms":5},{"id":"camere-mein-band-apahij","title":"कैमरे में बंद अपाहिज","section":"आरोह","summary":"रघुवीर सहाय की इस कविता में दूरदर्शन के एक कार्यक्रम के माध्यम से मीडिया की संवेदनहीनता पर व्यंग्य है, जो करुणा का दिखावा करते हुए एक अपाहिज व्यक्ति के दुख को बेचकर कार्यक्रम को रोचक बनाना चाहता है।","nTerms":5},{"id":"usha","title":"उषा","section":"आरोह","summary":"शमशेर बहादुर सिंह की 'उषा' सूर्योदय से ठीक पहले के पल-पल बदलते आकाश का शब्द-चित्र है। कवि ने गाँव की सुबह से जुड़े उपमानों – राख से लीपा चौका, सिल, स्लेट और खड़िया – के सहारे भोर को जीवंत बना दिया है।","nTerms":6},{"id":"badal-raag","title":"बादल राग","section":"आरोह","summary":"निराला की 'बादल राग' (अनामिका के छह खंडों में से छठा) में बादल क्रांति और नवनिर्माण का प्रतीक है। कवि शोषित किसान-मज़दूर और छोटे पौधों जैसे 'लघुमानव' की ओर से विप्लव के बादल का आह्वान करता है।","nTerms":6},{"id":"kavitavali-lakshman-murchha","title":"कवितावली (उत्तरकांड से), लक्ष्मण-मूर्च्छा और राम का विलाप","section":"आरोह","summary":"तुलसीदास के 'कवितावली' के छंदों में तत्कालीन समाज की गरीबी, भूख और बेरोज़गारी का यथार्थ तथा कवि का स्वाभिमान व्यक्त है; 'रामचरितमानस' के लंकाकांड से लिए गए अंश में लक्ष्मण के मूर्च्छित होने पर राम के करुण विलाप और हनुमान के आगमन का वर्णन है।","nTerms":6},{"id":"rubaiyan","title":"रुबाइयाँ","section":"आरोह","summary":"फ़िराक गोरखपुरी की रुबाइयों में माँ और बच्चे के वात्सल्य के घरेलू चित्र हैं – बच्चे को झुलाना, नहलाना, कपड़े पहनाना, दीवाली की शाम दीप जलाना, चाँद के लिए ज़िद करना और रक्षाबंधन की सुबह भाई की कलाई पर राखी बाँधना।","nTerms":6},{"id":"chhota-mera-khet-bagulon-ke-pankh","title":"छोटा मेरा खेत, बगुलों के पंख","section":"आरोह","summary":"उमाशंकर जोशी की 'छोटा मेरा खेत' में कागज़ के पन्ने को खेत मानकर कविता-रचना की प्रक्रिया को खेती के रूपक में बाँधा गया है। 'बगुलों के पंख' में बादलों भरे आकाश में पंक्तिबद्ध उड़ते सफ़ेद बगुलों के सौंदर्य का मोहक चित्र है।","nTerms":5},{"id":"bhaktin","title":"भक्तिन","section":"आरोह","summary":"महादेवी वर्मा के इस संस्मरणात्मक रेखाचित्र में उनकी सेविका भक्तिन के संघर्षपूर्ण जीवन, स्वाभिमानी और विरोधाभासी व्यक्तित्व तथा लेखिका के प्रति उसकी अनन्य निष्ठा का चित्रण है। साथ ही ग्रामीण समाज में स्त्री की दयनीय दशा भी उजागर होती है।","nTerms":6},{"id":"bazaar-darshan","title":"बाज़ार दर्शन","section":"आरोह","summary":"जैनेंद्र कुमार के इस विचारात्मक निबंध में बाज़ार के आकर्षण, उपभोक्तावाद और 'पर्चेज़िंग पावर' के प्रदर्शन की प्रवृत्ति का विश्लेषण है। लेखक बताते हैं कि बाज़ार की सार्थकता ज़रूरत के अनुसार ख़रीदारी में है और संतोषी मन पर बाज़ार का जादू नहीं चलता।","nTerms":6},{"id":"kale-megha-pani-de","title":"काले मेघा पानी दे","section":"आरोह","summary":"धर्मवीर भारती के इस संस्मरण में वर्षा के लिए निकलने वाली इंदर सेना और लेखक की जीजी के बहाने विज्ञान के तर्क और लोक-विश्वास के द्वंद्व को दिखाया गया है। जीजी का त्याग और बुवाई-जैसा तर्क लेखक के मन में सदा के लिए बस जाता है।","nTerms":6},{"id":"pahalwan-ki-dholak","title":"पहलवान की ढोलक","section":"आरोह","summary":"फणीश्वरनाथ रेणु की इस आंचलिक कहानी में महामारी से जूझते गाँव में लुट्टन पहलवान की ढोलक जीवन और साहस का संचार करती है। कहानी व्यवस्था बदलने पर लोक-कलाओं और कलाकारों की उपेक्षा की त्रासदी को भी दिखाती है।","nTerms":6},{"id":"shirish-ke-phool","title":"शिरीष के फूल","section":"आरोह","summary":"हजारी प्रसाद द्विवेदी के ललित निबंध 'शिरीष के फूल' में जेठ की झुलसाती गरमी में भी लहलहाने वाला शिरीष अवधूत की तरह अजेय जिजीविषा, अनासक्ति और संघर्षशीलता का प्रतीक है। लेखक उसके बहाने कवि-धर्म, पुरानी-नई पीढ़ी के द्वंद्व और गांधी जी के आत्मबल की याद करता है।","nTerms":6},{"id":"shram-vibhajan-aur-jati-pratha","title":"श्रम विभाजन और जाति-प्रथा, मेरी कल्पना का आदर्श समाज","section":"आरोह","summary":"डॉ. भीमराव आंबेडकर के भाषण 'जाति-भेद का उच्छेद' के इन दो अंशों में वे तर्क देते हैं कि जाति-प्रथा श्रम का नहीं, श्रमिकों का विभाजन है और मनुष्य की स्वतंत्रता व कुशलता को कुचलती है। दूसरे अंश में वे स्वतंत्रता, समता और भ्रातृता पर आधारित आदर्श समाज की रूपरेखा रखते हैं।","nTerms":5},{"id":"silver-wedding","title":"सिल्वर वैडिंग","section":"वितान","summary":"मनोहर श्याम जोशी की इस लंबी कहानी में पुराने संस्कारों वाले सरकारी अधिकारी यशोधर बाबू और उनके आधुनिक जीवन-शैली वाले परिवार के बीच के टकराव के माध्यम से पीढ़ी-अंतराल (जनरेशन गैप) का मार्मिक चित्रण है।","nTerms":6},{"id":"joojh","title":"जूझ","section":"वितान","summary":"मराठी कथाकार आनंद यादव के आत्मकथात्मक उपन्यास 'जूझ' के इस अंश में एक किसान परिवार के बालक के पढ़ाई के लिए किए गए संघर्ष, माँ के सहयोग और एक अध्यापक की प्रेरणा से उसके भीतर कवि के जन्म की कहानी है।","nTerms":6},{"id":"atit-mein-dabe-paon","title":"अतीत में दबे पाँव","section":"वितान","summary":"ओम थानवी के इस यात्रा-वृत्तांत में सिंधु घाटी सभ्यता के सबसे बड़े नगर मुअनजो-दड़ो की यात्रा का वर्णन है। लेखक नगर-नियोजन, जल-निकासी, घरों और संग्रहालय के बहाने बताता है कि वह सभ्यता साधन-संपन्न होकर भी भव्यता के आडंबर से दूर, ताकत से नहीं बल्कि आपसी समझ से अनुशासित थी।","nTerms":6},{"id":"patrakariya-lekhan-ke-vividh-roop","title":"पत्रकारीय लेखन के विभिन्न रूप","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"पत्रकारीय लेखन का स्वरूप, साहित्यिक लेखन से उसका अंतर, अच्छे लेखन के गुण तथा फ़ीचर, विशेष रिपोर्ट, संपादकीय, स्तंभ, लेख (आलेख), संपादक के नाम पत्र और साक्षात्कार जैसे इसके विभिन्न रूपों का परिचय।","nTerms":6},{"id":"vishesh-lekhan","title":"विशेष लेखन – स्वरूप और प्रकार","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"किसी ख़ास विषय – जैसे खेल, व्यापार, विज्ञान, कृषि या पर्यावरण – पर सामान्य लेखन से हटकर किया गया लेखन विशेष लेखन है। इस अध्याय में डेस्क, बीट, बीट रिपोर्टिंग और विशेषीकृत रिपोर्टिंग, विशेष लेखन की भाषा-शैली और विशेषज्ञता पाने के तरीके दिए गए हैं।","nTerms":6},{"id":"kahani-ka-natya-roopantaran","title":"कहानी का नाट्य रूपांतरण","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"कहानी को नाटक में बदलने के लिए दोनों विधाओं की समानताओं और अंतरों को समझना ज़रूरी है। इस अध्याय में रूपांतरण की प्रक्रिया – दृश्य-विभाजन, पात्र और संवाद, ध्वनि-प्रकाश तथा आने वाली कठिनाइयाँ – दी गई हैं।","nTerms":5},{"id":"radio-natak","title":"कैसे बनता है रेडियो नाटक","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"रेडियो नाटक पूरी तरह श्रव्य माध्यम है, जिसमें संवाद, ध्वनि प्रभाव और संगीत ही सब कुछ कहते हैं। इस अध्याय में रेडियो नाटक का स्वरूप, सिनेमा-रंगमंच से अंतर, कहानी, अवधि, पात्रों की संख्या और आलेख लिखने के नियम दिए गए हैं।","nTerms":6},{"id":"naye-aur-apratyashit-vishayon-par-lekhan","title":"नए और अप्रत्याशित विषयों पर लेखन","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"ऐसे विषयों पर लिखना, जिनकी पहले से तैयारी न हो, विद्यार्थी की मौलिक सोच और अभिव्यक्ति की परीक्षा है। इस अध्याय में ऐसे लेखन का महत्त्व, उसकी बाधाएँ, लिखने का ढंग, मूल्यांकन के बिंदु और एक आदर्श उत्तर दिया गया है।","nTerms":5},{"id":"aupcharik-patra","title":"औपचारिक पत्र","section":"अभिव्यक्ति और माध्यम (लेखन)","summary":"संपादक, अधिकारियों और संस्थाओं को किसी सार्वजनिक समस्या, शिकायत, अनुरोध या आवेदन के लिए लिखे जाने वाले पत्र औपचारिक पत्र कहलाते हैं। इस अध्याय में प्रारूप, संपादक को पत्र, आवेदन पत्र व स्ववृत्त और मूल्यांकन के बिंदु दिए गए हैं।","nTerms":5}]},"hindipb":{"syllabus":{"board":"PSEB","match":"textbook","books":["हिंदी भाषा बोध और व्याकरण (PSEB)","हिंदी साहित्य का इतिहास (PSEB)"],"note":"PSEB 2026–27 syllabus: grammar, history of Hindi literature and writing. Textbook lessons are not included.","reviewed":false},"chapters":[{"id":"samas-avyayibhav-tatpurush","title":"समास (अव्ययीभाव और तत्पुरुष)","section":"व्याकरण","summary":"दो या अधिक शब्दों के मेल से बने संक्षिप्त शब्द को समास कहते हैं। अव्ययीभाव समास में पूर्वपद प्रधान और अव्यय होता है; तत्पुरुष समास में उत्तरपद प्रधान होता है और कारक-चिह्न लुप्त रहता है।","nTerms":6},{"id":"samas-bahuvrihi-dvandva","title":"समास (बहुव्रीहि और द्वंद्व; कर्मधारय और द्विगु का संक्षिप्त परिचय)","section":"व्याकरण","summary":"बहुव्रीहि में दोनों पद मिलकर किसी तीसरे (अन्य) अर्थ का बोध कराते हैं; द्वंद्व में दोनों पद प्रधान होते हैं। कर्मधारय में विशेषण-विशेष्य और द्विगु में संख्या का भाव रहता है।","nTerms":5},{"id":"pad-parichay","title":"पद-परिचय","section":"व्याकरण","summary":"वाक्य में प्रयुक्त किसी शब्द (पद) का व्याकरणिक स्वरूप बताना पद-परिचय या पदान्वय कहलाता है। इसमें पद का भेद, लिंग, वचन, कारक और वाक्य के अन्य पदों से संबंध बताया जाता है।","nTerms":6},{"id":"paribhashik-shabd","title":"पारिभाषिक शब्द (J–Z)","section":"व्याकरण","summary":"प्रशासन, शिक्षा, न्याय और कार्यालय के कामकाज में प्रयुक्त अंग्रेज़ी शब्दों के निश्चित हिंदी पर्याय पारिभाषिक शब्द कहलाते हैं। यहाँ J से Z तक के प्रचलित प्रशासनिक शब्द दिए गए हैं।","nTerms":5},{"id":"chhand-doha-sortha-chaupai","title":"छंद (दोहा, सोरठा, चौपाई)","section":"व्याकरण","summary":"मात्राओं या वर्णों की गिनती और यति-गति के नियम से बँधी पद-रचना को छंद कहते हैं। दोहा और सोरठा अर्धसम मात्रिक छंद हैं (4 चरण), जबकि चौपाई सममात्रिक छंद है जिसके प्रत्येक चरण में 16 मात्राएँ होती हैं।","nTerms":5},{"id":"chhand-savaiya-kavitt","title":"छंद (सवैया और कवित्त)","section":"व्याकरण","summary":"सवैया और कवित्त वार्णिक छंद हैं, जिनमें वर्णों की गिनती होती है। सवैया के प्रत्येक चरण में 22 से 26 वर्ण होते हैं; कवित्त (मनहरण) के प्रत्येक चरण में 31 वर्ण होते हैं। रीतिकाल के कवियों ने इनका बहुत प्रयोग किया।","nTerms":5},{"id":"alankar-shabd","title":"अलंकार (अनुप्रास, यमक, श्लेष)","section":"व्याकरण","summary":"काव्य की शोभा बढ़ाने वाले तत्त्वों को अलंकार कहते हैं। जहाँ चमत्कार शब्दों पर आश्रित हो, वहाँ शब्दालंकार होता है – अनुप्रास (वर्णों की आवृत्ति), यमक (एक शब्द के भिन्न अर्थ में आवृत्ति) और श्लेष (एक शब्द के एक बार प्रयोग में अनेक अर्थ)।","nTerms":5},{"id":"alankar-arth","title":"अलंकार (उपमा और रूपक)","section":"व्याकरण","summary":"जहाँ चमत्कार अर्थ में हो, वहाँ अर्थालंकार होता है। उपमा में दो भिन्न वस्तुओं की समानता बताई जाती है; इसके चार अंग हैं – उपमेय, उपमान, वाचक शब्द और साधारण धर्म। रूपक में उपमेय पर उपमान का अभेद आरोप होता है।","nTerms":6},{"id":"ritikal","title":"रीतिकाल","section":"साहित्य का इतिहास","summary":"रीतिकाल हिंदी साहित्य के इतिहास में भक्तिकाल के बाद का काल है (मोटे तौर पर 1700 से 1900 वि.सं., अर्थात लगभग 1643 से 1843 ई.)। इसमें काव्यांग-निरूपण (रीति) की परंपरा और शृंगार रस की प्रधानता रही। कवियों को रीतिबद्ध, रीतिसिद्ध और रीतिमुक्त – तीन वर्गों में बाँटा जाता है।","nTerms":5},{"id":"bhartendu-dwivedi-yug","title":"आधुनिक काल: भारतेंदु युग और द्विवेदी युग","section":"साहित्य का इतिहास","summary":"आधुनिक काल का आरंभ लगभग 1850 ई. से माना जाता है। भारतेंदु हरिश्चंद्र के नेतृत्व में नवजागरण की चेतना आई और खड़ी बोली गद्य का विकास हुआ; महावीर प्रसाद द्विवेदी के संपादन में 'सरस्वती' पत्रिका ने भाषा को परिष्कृत किया और खड़ी बोली को काव्य की भाषा बनाया।","nTerms":5},{"id":"chhayavad","title":"आधुनिक काल: छायावाद","section":"साहित्य का इतिहास","summary":"छायावाद (लगभग 1918–1936 ई.) हिंदी कविता की वह धारा है जिसमें वैयक्तिकता, प्रकृति-प्रेम, कल्पना, रहस्यवाद और सौंदर्य-बोध प्रमुख हैं। इसके चार प्रमुख स्तंभ हैं – जयशंकर प्रसाद, सुमित्रानंदन पंत, सूर्यकांत त्रिपाठी 'निराला' और महादेवी वर्मा।","nTerms":5},{"id":"pragativad-prayogvad","title":"आधुनिक काल: प्रगतिवाद, प्रयोगवाद और नई कविता","section":"साहित्य का इतिहास","summary":"छायावाद के बाद हिंदी कविता में यथार्थ की ओर मोड़ आया। प्रगतिवाद (लगभग 1936 से) सामाजिक यथार्थ और शोषित वर्ग की आवाज़ बना; प्रयोगवाद की शुरुआत अज्ञेय द्वारा संपादित 'तार सप्तक' (1943) से मानी जाती है; नई कविता (1950 के बाद) में अनुभव की प्रामाणिकता और नए शिल्प पर बल रहा।","nTerms":5},{"id":"nibandh-lekhan","title":"निबंध लेखन","section":"लेखन","summary":"निबंध किसी विषय पर क्रमबद्ध, सुसंगत और प्रभावी गद्य-रचना है। अच्छे निबंध में भूमिका, विषय का विस्तार (मध्य) और उपसंहार होता है। पहले रूपरेखा बनाकर लिखने से निबंध सुव्यवस्थित बनता है।","nTerms":4},{"id":"punjabi-hindi-anuvad","title":"पंजाबी गद्यांश का हिंदी अनुवाद","section":"लेखन","summary":"अनुवाद का अर्थ है एक भाषा के भाव को दूसरी भाषा में सही रूप में प्रस्तुत करना। पंजाबी और हिंदी की व्याकरण-रचना काफ़ी मिलती है, फिर भी शब्दों, कारक-चिह्नों और क्रिया-रूपों में अंतर होता है, जिन पर ध्यान देना आवश्यक है।","nTerms":4},{"id":"vigyapan-lekhan","title":"विज्ञापन लेखन","section":"लेखन","summary":"विज्ञापन किसी वस्तु, सेवा या कार्यक्रम की जानकारी जनता तक पहुँचाने और उसे आकर्षित करने का माध्यम है। प्रभावी विज्ञापन संक्षिप्त, आकर्षक, स्पष्ट और विश्वसनीय होता है।","nTerms":4},{"id":"suchna-lekhan","title":"सूचना लेखन","section":"लेखन","summary":"सूचना किसी कार्यक्रम, बैठक या परिवर्तन के बारे में संबंधित लोगों को दी जाने वाली संक्षिप्त लिखित जानकारी है। स्कूलों और कार्यालयों में यह नोटिस-बोर्ड पर लगाई जाती है।","nTerms":4}]},"history":{"syllabus":{"board":"CBSE","match":"textbook","books":["Themes in Indian History Part I","Part II","Part III"],"reviewed":false},"chapters":[{"id":"bricks-beads-and-bones","title":"Bricks, Beads and Bones","section":"Part I – Ancient India","summary":"The Harappan (Indus) civilisation: its discovery, town planning, crafts, trade and agriculture, the evidence used to study it, and theories about its decline.","nTerms":6},{"id":"kings-farmers-and-towns","title":"Kings, Farmers and Towns","section":"Part I – Ancient India","summary":"Early states and economies from about 600 BCE to 600 CE: the rise of Magadha, the Mauryan empire and Ashoka, kingship, villages and farmers, towns, coins and trade, and how inscriptions are read.","nTerms":6},{"id":"kinship-caste-and-class","title":"Kinship, Caste and Class","section":"Part I – Ancient India","summary":"Social history through the Mahabharata: kinship and marriage rules, the varna and jati system, gender and property, and how historians read the epic.","nTerms":6},{"id":"thinkers-beliefs-and-buildings","title":"Thinkers, Beliefs and Buildings","section":"Part I – Ancient India","summary":"Cultural developments from about 600 BCE to 600 CE: new religious ideas of the Buddha and Mahavira, the Vedic and Brahmanical tradition, the stupa at Sanchi, and the growth of devotion and temples.","nTerms":6},{"id":"through-the-eyes-of-travellers","title":"Through the Eyes of Travellers","section":"Part II – Medieval India","summary":"What the accounts of Al-Biruni, Ibn Battuta and François Bernier reveal about India between the tenth and seventeenth centuries, and how to read travellers' writings critically.","nTerms":5},{"id":"bhakti-sufi-traditions","title":"Bhakti–Sufi Traditions","section":"Part II – Medieval India","summary":"Changes in religious belief and devotional literature from the eighth to the eighteenth century: the Alvars and Nayanars, Virashaivas, saints of north India, Sufi silsilas and the sant tradition.","nTerms":6},{"id":"an-imperial-capital-vijayanagara","title":"An Imperial Capital: Vijayanagara","section":"Part II – Medieval India","summary":"The city of Vijayanagara (Hampi) and the empire of the fourteenth to sixteenth centuries: its rulers, military and political system, the sacred centre, the royal centre and what archaeology and travellers tell us.","nTerms":5},{"id":"peasants-zamindars-and-the-state","title":"Peasants, Zamindars and the State","section":"Part II – Medieval India","summary":"Agrarian society under the Mughals in the sixteenth and seventeenth centuries: peasants and village communities, the role of zamindars, the land revenue system and the Ain-i-Akbari as a source.","nTerms":6},{"id":"colonialism-and-the-countryside","title":"Colonialism and the Countryside","section":"Part III – Modern India","summary":"How British land revenue policies, from the Permanent Settlement in Bengal to the Deccan, changed rural society, and how the Paharias, Santhals and Deccan ryots responded.","nTerms":6},{"id":"rebels-and-the-raj","title":"Rebels and the Raj","section":"Part III – Modern India","summary":"The revolt of 1857: its causes, spread and leaders, the rebels' shared symbols, the British response and the sources through which it is studied.","nTerms":5},{"id":"mahatma-gandhi-and-the-nationalist-movement","title":"Mahatma Gandhi and the Nationalist Movement","section":"Part III – Modern India","summary":"Gandhi's return to India in 1915, the movements he led from Champaran to Quit India, the Non-Cooperation, Civil Disobedience and Quit India movements, and the road to the end of British rule.","nTerms":5},{"id":"framing-the-constitution","title":"Framing the Constitution","section":"Part III – Modern India","summary":"The making of India's Constitution (1946–1950): the Constituent Assembly, the Objectives Resolution, the debates on rights, language and the state, and the Constitution's adoption.","nTerms":5}]},"historypb":{"syllabus":{"board":"PSEB","match":"textbook","books":["History of the Punjab (PSEB, Class 12)"],"note":"Follows the PSEB 2026–27 syllabus; written from the syllabus topics, not the PSEB book's own text.","reviewed":false},"chapters":[{"id":"physical-features","title":"Physical Features of the Punjab and their Influence on its History","section":"Part A","summary":"The land of the five rivers, its main regions and the way geography shaped Punjab's farming, its role as the gateway to India and the character of its people.","nTerms":5},{"id":"sources-of-punjab-history","title":"Sources of the History of the Punjab","section":"Part A","summary":"The literary, archaeological and foreign sources that historians use for the history of the Punjab and the Sikhs, and how far each can be trusted.","nTerms":5},{"id":"conditions-early-16th-century","title":"Political, Social and Economic Conditions of the Punjab in the Early 16th Century","section":"Part A","summary":"The Punjab at the time of the birth of Sikhism: Lodi rule and its weakness, a divided and unequal society, the condition of women, farming and trade, and the religious setting of Bhakti and Sufism.","nTerms":5},{"id":"guru-nanak-dev-ji","title":"Sri Guru Nanak Dev Ji's Life and Teachings","section":"Part A","summary":"The life, travels and message of the founder of Sikhism, and the institutions he began at Kartarpur.","nTerms":5},{"id":"gurus-angad-amar-das-ram-das","title":"Development of Sikhism under Sri Guru Angad Dev Ji, Sri Guru Amar Das Ji and Sri Guru Ram Das Ji","section":"Part A","summary":"How the second, third and fourth Gurus strengthened the Sikh community through Gurmukhi, langar, manjis, social reform and the founding of Amritsar.","nTerms":5},{"id":"guru-arjan-dev-ji","title":"Sri Guru Arjan Dev Ji and his Martyrdom","section":"Part A","summary":"The work of the fifth Guru in building Harmandir Sahib, compiling the Adi Granth and organising the community, and the events leading to his martyrdom at Lahore in 1606.","nTerms":5},{"id":"guru-hargobind-sahib-ji","title":"Sri Guru Hargobind Sahib Ji and the Transformation of Sikhism","section":"Part A","summary":"How the sixth Guru added military and political strength to the Sikh faith through the Akal Takht, miri and piri, and his encounters with the Mughals.","nTerms":5},{"id":"guru-har-rai-ji-and-har-krishan-ji","title":"Sri Guru Har Rai Ji and Sri Guru Har Krishan Ji","section":"Part A","summary":"The seventh and eighth Gurus: Guru Har Rai Ji's peaceful consolidation and service, and the short life of the child Guru Har Krishan Ji.","nTerms":4},{"id":"guru-tegh-bahadur-ji","title":"Sri Guru Tegh Bahadur Ji and his Martyrdom","section":"Part A","summary":"The ninth Guru's travels and preaching, the founding of Anandpur Sahib, and his martyrdom at Delhi in 1675 in defence of religious freedom.","nTerms":4},{"id":"guru-gobind-singh-ji","title":"Sri Guru Gobind Singh Ji: the Khalsa, his Battles and Personality","section":"Part A","summary":"The tenth Guru: his early life, the creation of the Khalsa in 1699, his battles with the hill chiefs and the Mughals, his writings and his role in ending the line of personal Gurus.","nTerms":5},{"id":"banda-singh-bahadur","title":"Baba Banda Singh Bahadur","section":"Part A","summary":"The Sikh leader sent by Guru Gobind Singh Ji to Punjab: his conquests including Sirhind in 1710, his rule at Lohgarh, his fall and his execution at Delhi in 1716.","nTerms":5},{"id":"abdus-samad-zakariya-mir-mannu","title":"Abdus Samad Khan, Zakariya Khan and Mir Mannu: Relations with the Sikhs","section":"Part B","summary":"The Mughal governors of Lahore from 1713 to 1753 and their policy towards the Sikhs: repression, a brief compromise, and the Sikhs' survival and growth in spite of it.","nTerms":5},{"id":"dal-khalsa","title":"Rise of the Dal Khalsa and its Mode of Fighting","section":"Part B","summary":"The formation of the Dal Khalsa in 1748 under Jassa Singh Ahluwalia, its organisation, the Gurmata and rakhi systems, and the guerrilla methods used by the Sikhs.","nTerms":5},{"id":"social-economic-mughal-punjab","title":"Social and Economic Conditions of the Punjab under the Mughals","section":"Part B","summary":"Society, women, religion, education, agriculture, industry and trade in the Punjab during Mughal rule (1526–1752).","nTerms":5},{"id":"ahmad-shah-abdali","title":"Invasions of Ahmad Shah Abdali and the End of Mughal Rule in the Punjab","section":"Part B","summary":"Ahmad Shah Abdali's repeated invasions between 1747 and 1767, the Sikh response including the Vadda Ghallughara of 1762, and the collapse of Mughal authority in Punjab.","nTerms":5},{"id":"sikh-misls","title":"Origin and Growth of the Sikh Misls","section":"Part B","summary":"The twelve Sikh misls of the later eighteenth century, their organisation, main sardars and territories, and the reasons they were unable to stay united.","nTerms":5},{"id":"ranjit-singh-conquests","title":"Maharaja Ranjit Singh's Career and Conquests","section":"Part B","summary":"The rise of Ranjit Singh from chief of the Sukerchakia misl to Maharaja of the Punjab, his conquests from Lahore (1799) to Peshawar (1834), and the extent of his kingdom.","nTerms":5},{"id":"anglo-sikh-relations-1800-1839","title":"Anglo-Sikh Relations (1800–1839)","section":"Part B","summary":"Relations between Ranjit Singh and the British East India Company: the Treaty of Amritsar (1809), later disputes over Sindh and Ferozepur, and the Tripartite Treaty of 1838.","nTerms":5},{"id":"afghanistan-and-frontier-policy","title":"Ranjit Singh's Relations with Afghanistan and North-West Frontier Policy","section":"Part B","summary":"Ranjit Singh's struggle with the Afghans for Attock, Multan, Kashmir and Peshawar, the battles of Naushera and Jamrud, and how he governed the turbulent frontier.","nTerms":5},{"id":"ranjit-singh-administration","title":"Civil and Military Administration of Maharaja Ranjit Singh","section":"Part B","summary":"How Ranjit Singh governed: the central and provincial administration, the revenue and justice systems, and the reorganisation of the Sikh army on modern lines.","nTerms":5},{"id":"ranjit-singh-personality","title":"Character and Personality of Maharaja Ranjit Singh","section":"Part B","summary":"An assessment of Ranjit Singh as soldier, statesman and ruler: his courage, tolerance and practical sense, and his limitations.","nTerms":5},{"id":"first-anglo-sikh-war","title":"First Anglo-Sikh War: Causes and Results","section":"Part B","summary":"The war of 1845–46: the instability after Ranjit Singh, British preparations, the battles from Mudki to Sobraon, and the Treaty of Lahore of 1846.","nTerms":5},{"id":"second-anglo-sikh-war","title":"Second Anglo-Sikh War and the Annexation of the Punjab","section":"Part B","summary":"The revolt at Multan, the battles of Chillianwala and Gujrat, and the annexation of the Punjab by Lord Dalhousie on 29 March 1849.","nTerms":5}]},"maths":{"syllabus":{"board":"CBSE","match":"textbook","books":["Mathematics Part I","Mathematics Part II"],"reviewed":false},"chapters":[{"id":"relations-and-functions","title":"Relations and Functions","section":"Relations and Functions","summary":"Types of relations (reflexive, symmetric, transitive, equivalence), types of functions (one-one, onto, bijective), composition of functions and invertible functions.","nTerms":6},{"id":"inverse-trigonometric-functions","title":"Inverse Trigonometric Functions","section":"Relations and Functions","summary":"Why trigonometric functions need restricted domains to have inverses, the domain and principal value branch of each inverse trigonometric function, their graphs, and how to find principal values.","nTerms":6},{"id":"matrices","title":"Matrices","section":"Algebra","summary":"Order and types of matrices, addition, scalar multiplication and multiplication of matrices, transpose, symmetric and skew-symmetric matrices, and invertible matrices.","nTerms":6},{"id":"determinants","title":"Determinants","section":"Algebra","summary":"Determinants of square matrices up to order 3, area of a triangle, minors and cofactors, adjoint and inverse of a matrix, and solving systems of linear equations by the matrix method.","nTerms":6},{"id":"continuity-and-differentiability","title":"Continuity and Differentiability","section":"Calculus","summary":"Continuity and differentiability of functions, the chain rule, derivatives of implicit, inverse trigonometric, exponential and logarithmic functions, logarithmic differentiation, parametric forms and second order derivatives.","nTerms":6},{"id":"application-of-derivatives","title":"Application of Derivatives","section":"Calculus","summary":"Using derivatives to find rates of change, to decide where a function is increasing or decreasing, and to find local and absolute maxima and minima in practical problems.","nTerms":6},{"id":"integrals","title":"Integrals","section":"Calculus","summary":"Integration as the inverse of differentiation, the methods of substitution, partial fractions and integration by parts, integrals of special forms, definite integrals, the fundamental theorem of calculus and properties of definite integrals.","nTerms":6},{"id":"application-of-integrals","title":"Application of Integrals","section":"Calculus","summary":"Using definite integrals to find the area under simple curves: lines, parabolas, circles and ellipses (in standard form).","nTerms":5},{"id":"differential-equations","title":"Differential Equations","section":"Calculus","summary":"Order and degree of a differential equation, general and particular solutions, and solving first order equations by separation of variables, the homogeneous method and the linear (integrating factor) method.","nTerms":6},{"id":"vector-algebra","title":"Vector Algebra","section":"Vectors and 3D Geometry","summary":"Vectors and their types, components and direction cosines, addition and scalar multiples, the section formula, and the scalar (dot) and vector (cross) products with their use for angles, projections and areas.","nTerms":6},{"id":"three-dimensional-geometry","title":"Three Dimensional Geometry","section":"Vectors and 3D Geometry","summary":"Direction cosines and direction ratios of a line, vector and Cartesian equations of a line, the angle between two lines, and the shortest distance between skew and parallel lines.","nTerms":6},{"id":"linear-programming","title":"Linear Programming","section":"Linear Programming","summary":"Formulating linear programming problems, feasible regions (bounded and unbounded), and finding the optimal value of a linear objective function by the graphical corner point method.","nTerms":6},{"id":"probability","title":"Probability","section":"Probability","summary":"Conditional probability, the multiplication theorem, independent events, the theorem of total probability, Bayes' theorem, and random variables with their probability distributions and mean.","nTerms":6}]},"physics":{"syllabus":{"board":"CBSE","match":"textbook","books":["Physics Part I","Physics Part II"],"reviewed":false},"chapters":[{"id":"electric-charges-and-fields","title":"Electric Charges and Fields","section":"Electrostatics","summary":"Charges at rest exert forces on each other. This chapter covers the properties of charge, Coulomb's law, the electric field and field lines, electric dipoles, electric flux, and Gauss's law with its applications.","nTerms":6},{"id":"electrostatic-potential-and-capacitance","title":"Electrostatic Potential and Capacitance","section":"Electrostatics","summary":"Electric potential describes the work done in moving charges in an electric field. This chapter covers potential due to charges and dipoles, equipotential surfaces, potential energy, conductors and dielectrics, and capacitors with their combinations and stored energy.","nTerms":6},{"id":"current-electricity","title":"Current Electricity","section":"Current Electricity","summary":"Electric current is the flow of charge through conductors. This chapter covers drift velocity, Ohm's law, resistivity and its temperature dependence, electrical power, cells with internal resistance, and Kirchhoff's rules with the Wheatstone bridge.","nTerms":6},{"id":"moving-charges-and-magnetism","title":"Moving Charges and Magnetism","section":"Magnetism","summary":"Moving charges and currents produce magnetic fields and feel forces in them. This chapter covers the Lorentz force, motion of charges in a magnetic field, the Biot–Savart law and Ampere's circuital law, forces between currents, torque on a current loop, and the moving coil galvanometer.","nTerms":6},{"id":"magnetism-and-matter","title":"Magnetism and Matter","section":"Magnetism","summary":"Magnets and magnetic materials are understood through the idea of magnetic dipoles. This chapter covers the bar magnet and its field lines, a magnetic dipole in a uniform field, Gauss's law for magnetism, magnetisation and magnetic intensity, and diamagnetic, paramagnetic and ferromagnetic substances.","nTerms":6},{"id":"electromagnetic-induction","title":"Electromagnetic Induction","section":"EMI and AC","summary":"A changing magnetic flux induces an emf in a circuit. This chapter covers magnetic flux, Faraday's and Lenz's laws, motional emf, self and mutual inductance, and the AC generator.","nTerms":6},{"id":"alternating-current","title":"Alternating Current","section":"EMI and AC","summary":"Alternating current changes direction periodically. This chapter covers rms values, AC through a resistor, an inductor and a capacitor, phasors, the series LCR circuit and resonance, power and power factor, and the transformer.","nTerms":6},{"id":"electromagnetic-waves","title":"Electromagnetic Waves","section":"Electromagnetic Waves","summary":"Changing electric and magnetic fields sustain each other and travel through space as electromagnetic waves. This chapter covers displacement current, the sources and nature of EM waves, and the electromagnetic spectrum with its uses.","nTerms":6},{"id":"ray-optics-and-optical-instruments","title":"Ray Optics and Optical Instruments","section":"Optics","summary":"Ray optics treats light as rays travelling in straight lines. This chapter covers reflection by spherical mirrors, refraction and total internal reflection, refraction at spherical surfaces and lenses, the lens maker's formula and power, refraction through a prism, and microscopes and telescopes.","nTerms":6},{"id":"wave-optics","title":"Wave Optics","section":"Optics","summary":"Wave optics explains interference, diffraction and polarisation, which ray optics cannot. This chapter covers Huygens principle, coherent sources and interference, Young's double-slit experiment, diffraction at a single slit, and polarisation.","nTerms":6},{"id":"dual-nature-of-radiation-and-matter","title":"Dual Nature of Radiation and Matter","section":"Modern Physics","summary":"Light and matter both show wave as well as particle properties. This chapter covers electron emission, the photoelectric effect and its laws, Einstein's photoelectric equation and photons, and de Broglie's matter waves.","nTerms":6},{"id":"atoms","title":"Atoms","section":"Modern Physics","summary":"This chapter traces how our model of the atom developed: Rutherford's nuclear model from alpha-particle scattering and its limitations, Bohr's model of the hydrogen atom with its energy levels and line spectrum, and de Broglie's explanation of Bohr's quantisation condition.","nTerms":6},{"id":"nuclei","title":"Nuclei","section":"Modern Physics","summary":"The nucleus is a tiny, very dense core of protons and neutrons held together by the nuclear force. This chapter covers the composition and size of nuclei, mass defect and binding energy, the binding energy curve, properties of nuclear force, and the energy released in fission and fusion.","nTerms":6},{"id":"semiconductor-electronics","title":"Semiconductor Electronics: Materials, Devices and Simple Circuits","section":"Electronics","summary":"Semiconductors are the basis of modern electronics. This chapter covers the classification of solids by resistivity and energy bands, intrinsic and extrinsic semiconductors, the p-n junction, the junction diode and its use as a rectifier.","nTerms":6}]},"polsci":{"syllabus":{"board":"CBSE","match":"textbook","books":["Contemporary World Politics","Politics in India since Independence"],"reviewed":false},"chapters":[{"id":"end-of-bipolarity","title":"The End of Bipolarity","section":"Contemporary World Politics","summary":"How the Soviet system worked, why the USSR disintegrated in 1991, how this ended the Cold War and bipolarity, the 'shock therapy' that followed in post-communist countries, the conflicts in the region, and India's relations with Russia.","nTerms":6},{"id":"new-centres-of-power","title":"New Centres of Power","section":"Contemporary World Politics","summary":"The organisations and countries that emerged as alternative centres of political and economic power after the Cold War: the European Union, ASEAN, the rise of China's economy, and Japan and South Korea.","nTerms":6},{"id":"contemporary-south-asia","title":"Contemporary South Asia","section":"Contemporary World Politics","summary":"The countries of South Asia and their experience of democracy, the conflicts and cooperation between India and its neighbours, SAARC and SAFTA, and the role of outside powers in the region.","nTerms":6},{"id":"international-organisations","title":"International Organisations","section":"Contemporary World Politics","summary":"Why we need international organisations, how the United Nations was formed and works, the debate on reforming the UN and India's claim to a permanent seat, and other key bodies like the IMF, World Bank, WTO, IAEA, Amnesty International and Human Rights Watch.","nTerms":6},{"id":"security-in-contemporary-world","title":"Security in the Contemporary World","section":"Contemporary World Politics","summary":"What security means, traditional (military) and non-traditional notions of security, new sources of threat like terrorism, poverty, migration and epidemics, cooperative security, and the components of India's security strategy.","nTerms":6},{"id":"environment-and-natural-resources","title":"Environment and Natural Resources","section":"Contemporary World Politics","summary":"How environmental issues entered world politics, global commons, the principle of common but differentiated responsibilities, India's stand on environmental issues, resource geopolitics, and the rights of indigenous peoples and environmental movements.","nTerms":6},{"id":"globalisation","title":"Globalisation","section":"Contemporary World Politics","summary":"The meaning and causes of globalisation, its political, economic and cultural consequences, India's experience of globalisation, and resistance to it in the world and in India.","nTerms":6},{"id":"challenges-of-nation-building","title":"Challenges of Nation Building","section":"Politics in India since Independence","summary":"The challenges India faced at independence: the partition and its consequences, the integration of the princely states, and the reorganisation of states on a linguistic basis.","nTerms":6},{"id":"era-of-one-party-dominance","title":"Era of One-Party Dominance","section":"Politics in India since Independence","summary":"How India held its first general elections, why the Congress dominated the first three elections, the nature of that dominance, and the main opposition parties of the time.","nTerms":6},{"id":"politics-of-planned-development","title":"Politics of Planned Development","section":"Politics in India since Independence","summary":"The political choices behind India's model of development: the Planning Commission and early Five Year Plans, the debates over agriculture versus industry and public versus private sector, and outcomes like land reforms, the Green Revolution and Operation Flood.","nTerms":6},{"id":"indias-external-relations","title":"India's External Relations","section":"Politics in India since Independence","summary":"India's foreign policy since independence: Nehru's non-alignment, Afro-Asian unity, relations and wars with China and Pakistan, the 1971 war and Bangladesh, and India's nuclear policy.","nTerms":6},{"id":"challenges-to-congress-system","title":"Challenges to and Restoration of the Congress System","section":"Politics in India since Independence","summary":"How the Congress dealt with political succession after Nehru, the setback of the 1967 elections, the split of 1969, and how Indira Gandhi restored Congress dominance in 1971 in a new form.","nTerms":6},{"id":"crisis-of-democratic-order","title":"The Crisis of Democratic Order","section":"Politics in India since Independence","summary":"The background to the Emergency of 1975–77, the movements in Gujarat and Bihar, the conflict with the judiciary, the declaration and consequences of the Emergency, the 1977 elections and the lessons for Indian democracy.","nTerms":6},{"id":"regional-aspirations","title":"Regional Aspirations","section":"Politics in India since Independence","summary":"How India has dealt with regional aspirations: the Dravidian movement, Jammu and Kashmir, Punjab, the North-East, Sikkim and Goa, and the lessons these experiences teach about accommodating diversity in a democracy.","nTerms":6},{"id":"recent-developments-in-indian-politics","title":"Recent Developments in Indian Politics","section":"Politics in India since Independence","summary":"Indian politics since the late 1980s: the end of Congress dominance, the era of coalitions, the political rise of OBCs and Dalits, communalism and the Ayodhya dispute, the elections of 2014 and 2019, and the growing consensus among parties.","nTerms":6}]},"polscipb":{"syllabus":{"board":"PSEB","match":"textbook","books":["Political Science (PSEB, Class 12)"],"note":"Follows the PSEB 2026–27 syllabus; written from the syllabus topics, not the PSEB book's own text.","reviewed":false},"chapters":[{"id":"comparative-politics","title":"Comparative Politics: Meaning, Nature and Scope","section":"Comparative Politics","summary":"What comparative politics studies, how it moved from the old institutional approach to the modern behavioural approach, and the areas it covers.","nTerms":4},{"id":"political-socialisation","title":"Political Socialisation","section":"Comparative Politics","summary":"How individuals acquire political values, attitudes and beliefs, the agencies that shape them and why the process matters for stability and change.","nTerms":4},{"id":"political-culture","title":"Political Culture","section":"Comparative Politics","summary":"The meaning of political culture, Almond and Verba's three types (parochial, subject, participant) and the factors that shape it.","nTerms":5},{"id":"political-system","title":"Political System (Easton's and Almond's Models)","section":"Comparative Politics","summary":"The concept of a political system, David Easton's input-output model and Almond and Powell's structural-functional approach.","nTerms":5},{"id":"public-opinion","title":"Public Opinion","section":"Comparative Politics","summary":"What public opinion is, how it is formed, the agencies that express and measure it, and its role in democracy.","nTerms":4},{"id":"bureaucracy","title":"Bureaucracy","section":"Comparative Politics","summary":"The meaning and features of bureaucracy, Max Weber's ideal type, its functions and the criticism it faces.","nTerms":4},{"id":"electoral-system","title":"Electoral System, Voting Behaviour and Participation","section":"Comparative Politics","summary":"Electoral systems (territorial and proportional representation), factors influencing voting behaviour and the forms and importance of political participation.","nTerms":5},{"id":"party-system","title":"Party System and Political Parties","section":"Comparative Politics","summary":"Functions of political parties, types of party systems and the nature of the Indian party system and its major parties.","nTerms":5},{"id":"interest-groups","title":"Interest Groups and Pressure Groups","section":"Comparative Politics","summary":"What interest and pressure groups are, how they differ from parties, their types, methods and role in democracy.","nTerms":4},{"id":"liberalism","title":"Liberalism","section":"Comparative Politics","summary":"The core ideas of classical (negative) liberalism and modern (positive) liberalism, and their views on freedom, the state and the market.","nTerms":5},{"id":"marxism","title":"Marxism","section":"Comparative Politics","summary":"The ideas of Karl Marx and Friedrich Engels: dialectical and historical materialism, class struggle, surplus value, the dictatorship of the proletariat and the withering away of the state.","nTerms":5},{"id":"gandhi","title":"Social and Political Ideas of Mahatma Gandhi","section":"Comparative Politics","summary":"Gandhi's ideas of truth, non-violence, satyagraha, swaraj, sarvodaya, trusteeship and decentralisation.","nTerms":6},{"id":"ambedkar","title":"Social, Economic and Political Ideas of Dr B. R. Ambedkar","section":"Comparative Politics","summary":"Ambedkar's thought on caste and social justice, social democracy, his economic ideas and his role in framing the Constitution.","nTerms":4},{"id":"local-self-government","title":"Local Self-Government: Concept and Challenges","section":"Political Processes in India","summary":"The idea of local self-government, its growth in India, the 73rd and 74th Amendments and the challenges faced.","nTerms":4},{"id":"rural-urban-local-bodies","title":"Rural and Urban Local Bodies","section":"Political Processes in India","summary":"Structure and functions of panchayats in rural areas and municipalities in urban areas.","nTerms":5},{"id":"politics-in-punjab","title":"Political Processes in Punjab","section":"Political Processes in India","summary":"A general account of Punjab's political history after 1947, reorganisation in 1966, the main parties and recurring themes.","nTerms":4},{"id":"parliamentary-model-opposition","title":"India's Parliamentary Model and the Role of the Opposition","section":"Political Processes in India","summary":"Features of India's parliamentary system and the functions of the Opposition in Parliament.","nTerms":5},{"id":"indian-democracy","title":"Indian Democracy: Determinants and Challenges","section":"Political Processes in India","summary":"The factors that have sustained democracy in India and the major challenges it faces.","nTerms":4},{"id":"nation-building","title":"Nation-Building: Processes and Problems","section":"Political Processes in India","summary":"How India built a united nation after Independence and the problems of integration it faced.","nTerms":4},{"id":"election-commission","title":"Election Commission","section":"Political Processes in India","summary":"The constitutional position, composition, powers and functions of the Election Commission of India.","nTerms":5},{"id":"foreign-policy","title":"India's Foreign Policy: Determinants and Principles","section":"India and the World","summary":"What shapes India's foreign policy and its guiding principles: Panchsheel, non-alignment, anti-colonialism and peaceful coexistence.","nTerms":4},{"id":"india-un-saarc","title":"India, the UN and SAARC","section":"India and the World","summary":"India's role in the United Nations and the South Asian Association for Regional Cooperation.","nTerms":4},{"id":"india-relations","title":"India's Relations with Pakistan, China, Russia and the USA","section":"India and the World","summary":"An overview of India's relations with four major countries: key events, areas of cooperation and disagreement.","nTerms":4},{"id":"world-issues","title":"Major World Issues: Human Rights, Disarmament, Globalisation, Migration","section":"India and the World","summary":"Human rights, nuclear disarmament, globalisation and migration as major global issues and India's position on them.","nTerms":5}]},"punjabi":{"syllabus":{"board":"CBSE","match":"textbook","books":["ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ-12"],"note":"ਵਿਆਕਰਨ ਅਤੇ ਲੇਖ ਰਚਨਾ, ਨਾਲ ਹੀ ਪੰਜਾਬ ਸਕੂਲ ਸਿੱਖਿਆ ਬੋਰਡ ਦੀ ਪੁਸਤਕ ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ-12 ਦੇ ਸਾਰੇ ਪਾਠ (ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਸੰਖੇਪ)।","reviewed":false},"chapters":[{"id":"punjabi-nikas","title":"ਪੰਜਾਬੀ ਭਾਸ਼ਾ ਦਾ ਨਿਕਾਸ ਤੇ ਵਿਕਾਸ","section":"ਭਾਸ਼ਾ ਬਾਰੇ ਜਾਣਕਾਰੀ","summary":"ਪੰਜਾਬੀ ਇੰਡੋ-ਆਰੀਅਨ ਭਾਸ਼ਾ ਪਰਿਵਾਰ ਦੀ ਭਾਸ਼ਾ ਹੈ ਅਤੇ ਇਸ ਦਾ ਸਫ਼ਰ ਪ੍ਰਾਚੀਨ ਭਾਸ਼ਾਵਾਂ ਤੋਂ ਹੁੰਦਾ ਹੋਇਆ ਆਧੁਨਿਕ ਰੂਪ ਤੱਕ ਪਹੁੰਚਿਆ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਨਿਕਾਸ, ਲਿਪੀਆਂ ਅਤੇ ਮੁੱਢਲੇ ਸਾਹਿਤ ਦੀ ਸੰਖੇਪ ਜਾਣਕਾਰੀ ਹੈ।","nTerms":5},{"id":"shabad-shreniyan","title":"ਸ਼ਬਦ-ਸ਼੍ਰੇਣੀਆਂ ਦੀ ਦੁਹਰਾਈ","section":"ਵਿਆਕਰਨ","summary":"ਪੰਜਾਬੀ ਦੇ ਸ਼ਬਦਾਂ ਨੂੰ ਉਹਨਾਂ ਦੇ ਕੰਮ ਅਨੁਸਾਰ ਵੱਖ-ਵੱਖ ਸ਼ਬਦ-ਸ਼੍ਰੇਣੀਆਂ ਵਿੱਚ ਰੱਖਿਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਨਾਂਵ, ਪੜਨਾਂਵ, ਵਿਸ਼ੇਸ਼ਣ ਅਤੇ ਹੋਰ ਸ਼੍ਰੇਣੀਆਂ ਦੀ ਦੁਹਰਾਈ ਹੈ।","nTerms":6},{"id":"vaak-banavat","title":"ਵਾਕ-ਬਣਤਰ","section":"ਵਿਆਕਰਨ","summary":"ਵਾਕ ਸ਼ਬਦਾਂ ਦਾ ਉਹ ਸਮੂਹ ਹੈ ਜੋ ਪੂਰਾ ਭਾਵ ਦਿੰਦਾ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਵਾਕ ਦੇ ਅੰਗ, ਸ਼ਬਦਾਂ ਦਾ ਕ੍ਰਮ ਅਤੇ ਸਰਲ, ਮਿਸ਼ਰਤ ਤੇ ਸੰਯੁਕਤ ਵਾਕਾਂ ਦੀ ਪਛਾਣ ਹੈ।","nTerms":6},{"id":"vaak-vattandra","title":"ਵਾਕ-ਵਟਾਂਦਰਾ","section":"ਵਿਆਕਰਨ","summary":"ਵਾਕ-ਵਟਾਂਦਰੇ ਵਿੱਚ ਵਾਕ ਦਾ ਰੂਪ ਜਾਂ ਕਿਸਮ ਬਦਲੀ ਜਾਂਦੀ ਹੈ, ਜਿਵੇਂ ਬਿਆਨੀਆ ਤੋਂ ਪ੍ਰਸ਼ਨਵਾਚਕ ਜਾਂ ਵਿਸਮਿਕ। ਇਸ ਪਾਠ ਵਿੱਚ ਹਰ ਕਿਸਮ ਦੀ ਪਛਾਣ ਅਤੇ ਬਦਲਣ ਦੇ ਢੰਗ ਹਨ।","nTerms":5},{"id":"shudh-ashudh","title":"ਸ਼ੁੱਧ-ਅਸ਼ੁੱਧ ਸ਼ਬਦ-ਜੋੜ","section":"ਵਿਆਕਰਨ","summary":"ਸ਼ੁੱਧ ਸ਼ਬਦ-ਜੋੜ ਲਿਖਤ ਦੀ ਪਹਿਲੀ ਪਛਾਣ ਹਨ। ਇਸ ਪਾਠ ਵਿੱਚ ਟਿੱਪੀ, ਅਧਕ, ਬਿੰਦੀ ਅਤੇ ਪੈਰ ਬਿੰਦੀ ਨਾਲ ਜੁੜੀਆਂ ਆਮ ਗ਼ਲਤੀਆਂ ਅਤੇ ਉਹਨਾਂ ਤੋਂ ਬਚਣ ਦੇ ਢੰਗ ਹਨ।","nTerms":5},{"id":"anuvaad","title":"ਅਨੁਵਾਦ: ਅੰਗਰੇਜ਼ੀ ਤੋਂ ਪੰਜਾਬੀ","section":"ਲੇਖ ਰਚਨਾ","summary":"ਅਨੁਵਾਦ ਵਿੱਚ ਮੂਲ ਵਾਕ ਦਾ ਭਾਵ ਅਤੇ ਅਰਥ ਠੀਕ ਰੱਖ ਕੇ ਉਸ ਨੂੰ ਕੁਦਰਤੀ ਪੰਜਾਬੀ ਵਿੱਚ ਲਿਖਿਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਵਾਕ-ਕ੍ਰਮ, ਕਾਲ, ਮੁਹਾਵਰੇ ਅਤੇ ਨਾਂਵਾਂ ਦੇ ਅਨੁਵਾਦ ਦੇ ਨਿਯਮ ਹਨ।","nTerms":5},{"id":"para-rachna","title":"ਪੈਰਾ ਰਚਨਾ","section":"ਲੇਖ ਰਚਨਾ","summary":"ਪੈਰਾ ਇੱਕ ਵਿਚਾਰ ਦਾ ਛੋਟਾ ਪਰ ਪੂਰਾ ਹਿੱਸਾ ਹੁੰਦਾ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਪੈਰੇ ਦੇ ਅੰਗ, ਜੋੜਨ ਵਾਲੇ ਸ਼ਬਦ ਅਤੇ ਚੰਗਾ ਪੈਰਾ ਲਿਖਣ ਦੇ ਢੰਗ ਹਨ।","nTerms":5},{"id":"report-likhna","title":"ਰਿਪੋਰਟ ਲਿਖਣਾ","section":"ਲੇਖ ਰਚਨਾ","summary":"ਰਿਪੋਰਟ ਕਿਸੇ ਘਟਨਾ ਜਾਂ ਕੰਮ ਦਾ ਤੱਥਾਂ ਉੱਤੇ ਆਧਾਰਿਤ, ਤਰਤੀਬਵਾਰ ਬਿਓਰਾ ਹੁੰਦੀ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਰਿਪੋਰਟ ਦਾ ਢਾਂਚਾ, ਭਾਸ਼ਾ ਅਤੇ ਸਿੱਟਾ ਲਿਖਣ ਦੇ ਢੰਗ ਹਨ।","nTerms":5},{"id":"binai-patar","title":"ਬਿਨੈ-ਪੱਤਰ","section":"ਲੇਖ ਰਚਨਾ","summary":"ਬਿਨੈ-ਪੱਤਰ ਕਿਸੇ ਅਧਿਕਾਰੀ ਅੱਗੇ ਨਿਮਰਤਾ ਨਾਲ ਕੋਈ ਬੇਨਤੀ ਜਾਂ ਮੰਗ ਰੱਖਣ ਲਈ ਲਿਖਿਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਇਸ ਦਾ ਢਾਂਚਾ, ਭਾਸ਼ਾ ਅਤੇ ਦਫ਼ਤਰੀ ਚਿੱਠੀ ਨਾਲ ਫ਼ਰਕ ਹੈ।","nTerms":5},{"id":"punjabi-sabhyachar","title":"ਪੰਜਾਬੀ ਸੱਭਿਆਚਾਰ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਡਾ. ਬਰਿੰਦਰ ਕੌਰ ਦਾ ਇਹ ਲੇਖ ਦੱਸਦਾ ਹੈ ਕਿ ਸੱਭਿਆਚਾਰ ਕੀ ਹੈ, ਪੰਜਾਬੀ ਸੱਭਿਆਚਾਰ ਦਾ ਇਤਿਹਾਸਿਕ ਪਿਛੋਕੜ ਕੀ ਹੈ, ਇਸ ਦੇ ਮੁੱਖ ਲੱਛਣ ਕਿਹੜੇ ਹਨ ਅਤੇ ਸਮੇਂ ਨਾਲ ਇਸ ਵਿੱਚ ਕਿਹੜੀਆਂ ਤਬਦੀਲੀਆਂ ਆ ਰਹੀਆਂ ਹਨ।","nTerms":5},{"id":"punjab-mele-tiuhar","title":"ਪੰਜਾਬ ਦੇ ਮੇਲੇ ਤੇ ਤਿਉਹਾਰ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਡਾ. ਐੱਸ.ਐੱਸ. ਵਣਜਾਰਾ ਬੇਦੀ ਦੇ ਇਸ ਲੇਖ ਵਿੱਚ ਪੰਜਾਬ ਦੇ ਮੇਲਿਆਂ ਦੇ ਮਹੱਤਵ, ਧਾਰਮਿਕ ਤੇ ਇਤਿਹਾਸਿਕ ਮੇਲਿਆਂ ਅਤੇ ਰੁੱਤਾਂ ਨਾਲ ਜੁੜੇ ਤਿਉਹਾਰਾਂ ਦੀ ਜਾਣਕਾਰੀ ਮਿਲਦੀ ਹੈ।","nTerms":5},{"id":"punjab-rasam-riwaj","title":"ਪੰਜਾਬ ਦੇ ਰਸਮ-ਰਿਵਾਜ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਗੁਲਜ਼ਾਰ ਸਿੰਘ ਸੰਧੂ ਦਾ ਇਹ ਲੇਖ ਜਨਮ, ਵਿਆਹ ਅਤੇ ਮੌਤ ਨਾਲ ਜੁੜੀਆਂ ਪੰਜਾਬੀ ਰਸਮਾਂ ਦਾ ਵੇਰਵਾ ਦਿੰਦਾ ਹੈ ਅਤੇ ਦੱਸਦਾ ਹੈ ਕਿ ਇਹ ਰਸਮਾਂ ਕਿਵੇਂ ਪੈਦਾ ਹੋਈਆਂ ਅਤੇ ਹੁਣ ਕਿਵੇਂ ਬਦਲ ਰਹੀਆਂ ਹਨ।","nTerms":5},{"id":"punjab-lok-khedan","title":"ਪੰਜਾਬ ਦੀਆਂ ਲੋਕ-ਖੇਡਾਂ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਸੁਖਦੇਵ ਮਾਦਪੁਰੀ ਦਾ ਲੇਖ ਦੱਸਦਾ ਹੈ ਕਿ ਲੋਕ-ਖੇਡਾਂ ਪੇਂਡੂ ਜੀਵਨ ਦਾ ਅਨਿੱਖੜਵਾਂ ਅੰਗ ਹਨ, ਇਹ ਸਰੀਰ ਅਤੇ ਮਨ ਦਾ ਵਿਕਾਸ ਕਰਦੀਆਂ ਹਨ ਅਤੇ ਬੱਚਿਆਂ ਤੇ ਗੱਭਰੂਆਂ ਦੀਆਂ ਕਈ ਪ੍ਰਸਿੱਧ ਖੇਡਾਂ ਦਾ ਜ਼ਿਕਰ ਕਰਦਾ ਹੈ।","nTerms":5},{"id":"punjab-lok-kitte-kalavan","title":"ਪੰਜਾਬ ਦੇ ਲੋਕ-ਕਿੱਤੇ ਅਤੇ ਲੋਕ-ਕਲਾਵਾਂ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਕਿਰਪਾਲ ਕਜ਼ਾਕ ਦਾ ਲੇਖ ਦੱਸਦਾ ਹੈ ਕਿ ਲੋਕ-ਕਿੱਤੇ ਲੋੜਾਂ ਤੋਂ ਕਿਵੇਂ ਪੈਦਾ ਹੋਏ, ਪੰਜਾਬ ਦੇ ਪ੍ਰਮੁੱਖ ਕਿੱਤੇ ਅਤੇ ਹੱਥ-ਕਲਾਵਾਂ (ਖ਼ਾਸ ਕਰਕੇ ਫੁਲਕਾਰੀ) ਕਿਹੋ ਜਿਹੀਆਂ ਹਨ ਅਤੇ ਮਸ਼ੀਨਾਂ ਨੇ ਇਹਨਾਂ ਨੂੰ ਕਿਵੇਂ ਬਦਲਿਆ।","nTerms":5},{"id":"punjab-lok-nach","title":"ਪੰਜਾਬ ਦੇ ਲੋਕ-ਨਾਚ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਡਾ. ਜਗੀਰ ਸਿੰਘ ਨੂਰ ਦਾ ਲੇਖ ਦੱਸਦਾ ਹੈ ਕਿ ਲੋਕ-ਨਾਚ ਇੱਕ ਲੋਕ-ਕਲਾ ਹਨ ਜੋ ਜਨ-ਜੀਵਨ ਦੀਆਂ ਭਾਵਨਾਵਾਂ ਪ੍ਰਗਟ ਕਰਦੀ ਹੈ, ਅਤੇ ਇਸਤਰੀਆਂ ਤੇ ਮਰਦਾਂ ਦੇ ਪ੍ਰਮੁੱਖ ਨਾਚਾਂ ਦਾ ਵੇਰਵਾ ਦਿੰਦਾ ਹੈ।","nTerms":5},{"id":"punjab-diyan-nakalan","title":"ਪੰਜਾਬ ਦੀਆਂ ਨਕਲਾਂ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਪਿਆਰਾ ਸਿੰਘ ਖੁੰਡਾ ਦਾ ਇਹ ਲੇਖ ਪੰਜਾਬ ਦੀ ਲੋਕ-ਨਾਟ ਵਿਧਾ 'ਨਕਲਾਂ' ਬਾਰੇ ਹੈ: ਇਸ ਦਾ ਸਰੂਪ, ਨਕਲੀਏ, ਪੇਸ਼ਕਾਰੀ ਦਾ ਢੰਗ, ਅਖਾੜੇ ਦੀਆਂ ਕਿਸਮਾਂ ਅਤੇ ਸਮਾਜ ਵਿੱਚ ਇਸ ਦਾ ਮਹੱਤਵ।","nTerms":5},{"id":"punjabi-sabhyacharik-parivartan","title":"ਪੰਜਾਬੀ ਸੱਭਿਆਚਾਰਿਕ ਪਰਿਵਰਤਨ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਡਾ. ਰਾਜਿੰਦਰਪਾਲ ਸਿੰਘ ਬਰਾੜ ਦਾ ਇਹ ਲੇਖ ਦੱਸਦਾ ਹੈ ਕਿ ਸੱਭਿਆਚਾਰ ਇੱਕ ਵਗਦੇ ਦਰਿਆ ਵਾਂਗ ਹੈ ਜੋ ਬਦਲਦਾ ਰਹਿੰਦਾ ਹੈ, ਅਤੇ ਪੰਜਾਬੀ ਸੱਭਿਆਚਾਰ ਵਿੱਚ ਆਈਆਂ ਤਬਦੀਲੀਆਂ ਦੇ ਕਾਰਨ ਅਤੇ ਨਤੀਜੇ ਸਮਝਾਉਂਦਾ ਹੈ।","nTerms":5},{"id":"karvihar-de-patar","title":"ਕਾਰ-ਵਿਹਾਰ ਦੇ ਪੱਤਰ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਇਸ ਪਾਠ ਵਿੱਚ ਵਪਾਰਿਕ ਜਾਂ ਕਾਰ-ਵਿਹਾਰ ਦੇ ਪੱਤਰ ਲਿਖਣ ਦੀ ਲੋੜ, ਇਹਨਾਂ ਦੀਆਂ ਕਿਸਮਾਂ, ਲਿਖਣ ਸਮੇਂ ਧਿਆਨ ਰੱਖਣ ਵਾਲੀਆਂ ਗੱਲਾਂ ਅਤੇ ਨਮੂਨੇ ਦੇ ਪੱਤਰਾਂ ਦਾ ਢਾਂਚਾ ਦੱਸਿਆ ਗਿਆ ਹੈ।","nTerms":5},{"id":"sankhep-rachna","title":"ਸੰਖੇਪ ਰਚਨਾ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਸੰਖੇਪ ਰਚਨਾ (ਪ੍ਰੈਸੀ) ਕਿਸੇ ਲੰਮੀ ਰਚਨਾ ਦੇ ਸਾਰ ਨੂੰ ਸਰਲ, ਸਪਸ਼ਟ ਅਤੇ ਘੱਟ ਸ਼ਬਦਾਂ ਵਿੱਚ ਲਿਖਣ ਦੀ ਕਲਾ ਹੈ। ਇਸ ਪਾਠ ਵਿੱਚ ਇਸ ਦੇ ਗੁਰ, ਪੜਾਅ ਅਤੇ ਨਮੂਨੇ ਦਿੱਤੇ ਗਏ ਹਨ।","nTerms":5},{"id":"shabad-kosh-vachan-vidhi","title":"ਸ਼ਬਦ-ਕੋਸ਼: ਵਾਚਣ-ਵਿਧੀ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਇਸ ਪਾਠ ਵਿੱਚ ਕੋਸ਼ ਦੀ ਪਰਿਭਾਸ਼ਾ, ਇਸ ਦੀਆਂ ਕਿਸਮਾਂ, ਪੰਜਾਬੀ ਕੋਸ਼ਕਾਰੀ ਦੇ ਮੁੱਢ ਅਤੇ ਸ਼ਬਦ-ਕੋਸ਼ ਵਿੱਚ ਸ਼ਬਦ ਲੱਭਣ ਦੇ ਨਿਯਮ (ਅੱਖਰ-ਤਰਤੀਬ, ਮਾਤਰਾਵਾਂ ਅਤੇ ਲਗਾਖਰ) ਸਮਝਾਏ ਗਏ ਹਨ।","nTerms":5},{"id":"vaak-kisman-vatandra","title":"ਵਾਕ ਦੀਆਂ ਕਿਸਮਾਂ ਅਤੇ ਵਾਕ-ਵਟਾਂਦਰਾ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਇਸ ਪਾਠ ਵਿੱਚ ਵਾਕਾਂਸ਼, ਉਪਵਾਕ ਤੇ ਵਾਕ ਦਾ ਸੰਬੰਧ, ਬਣਤਰ ਅਤੇ ਕਾਰਜ ਦੇ ਆਧਾਰ 'ਤੇ ਵਾਕ ਦੀਆਂ ਕਿਸਮਾਂ ਅਤੇ ਇੱਕ ਕਿਸਮ ਦੇ ਵਾਕ ਨੂੰ ਦੂਜੀ ਕਿਸਮ ਵਿੱਚ ਬਦਲਣ ਦੇ ਨਿਯਮ ਸਮਝਾਏ ਗਏ ਹਨ।","nTerms":5},{"id":"akhautan","title":"ਅਖਾਉਤਾਂ","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਅਖਾਉਤਾਂ (ਅਖਾਣ ਜਾਂ ਕਹਾਵਤਾਂ) ਲੋਕ-ਸੂਝ ਦਾ ਭੰਡਾਰ ਹੁੰਦੀਆਂ ਹਨ। ਇਸ ਪਾਠ ਵਿੱਚ ਅਖਾਉਤਾਂ ਦੀ ਮਹੱਤਤਾ ਅਤੇ ਕੁਝ ਅਖਾਉਤਾਂ ਦੇ ਅਰਥ ਤੇ ਵਰਤੋਂ ਵਾਕਾਂ ਵਿੱਚ ਦਿੱਤੇ ਗਏ ਹਨ।","nTerms":5},{"id":"kavita-tukri-jag-ton-niyari","title":"ਟੁਕੜੀ ਜੱਗ ਤੋਂ ਨਿਆਰੀ (ਭਾਈ ਵੀਰ ਸਿੰਘ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਭਾਈ ਵੀਰ ਸਿੰਘ ਦੀ ਇਹ ਕਵਿਤਾ ਕਸ਼ਮੀਰ ਦੀ ਸੁੰਦਰਤਾ ਦਾ ਵਰਨਣ ਇੱਕ ਸੁੰਦਰ ਕਲਪਨਾ ਰਾਹੀਂ ਕਰਦੀ ਹੈ ਕਿ ਕੁਦਰਤ ਦੇਵੀ ਨੇ ਅਰਸ਼ ਦੀਆਂ ਸਾਰੀਆਂ ਸੁੰਦਰ ਚੀਜ਼ਾਂ ਮੁੱਠੀ ਵਿੱਚ ਭਰ ਕੇ ਧਰਤੀ 'ਤੇ ਸੁੱਟ ਦਿੱਤੀਆਂ, ਜਿੱਥੇ ਕਸ਼ਮੀਰ ਬਣ ਗਿਆ।","nTerms":5},{"id":"kavita-purane-punjab-nu-awazan","title":"ਪੁਰਾਣੇ ਪੰਜਾਬ ਨੂੰ ਅਵਾਜ਼ਾਂ (ਪ੍ਰੋ. ਪੂਰਨ ਸਿੰਘ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਪ੍ਰੋ. ਪੂਰਨ ਸਿੰਘ ਦੀ ਇਹ ਛੰਦ-ਮੁਕਤ ਕਵਿਤਾ ਬੀਤ ਚੁੱਕੇ ਪੰਜਾਬ ਦੇ ਪਿਆਰ, ਆਦਰ, ਰਸਮਾਂ, ਵਿਆਹਾਂ, ਖੇਡਾਂ ਅਤੇ ਸਾਦੀ ਜੀਵਨ-ਜਾਚ ਨੂੰ ਯਾਦ ਕਰਦੀ ਹੈ ਅਤੇ ਨਵੀਂ ਸੱਭਿਅਤਾ ਪ੍ਰਤੀ ਉਦਾਸੀ ਪ੍ਰਗਟ ਕਰਦੀ ਹੈ।","nTerms":5},{"id":"kavita-vagde-pani","title":"ਵਗਦੇ ਪਾਣੀ (ਡਾ. ਦੀਵਾਨ ਸਿੰਘ ਕਾਲੇਪਾਣੀ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਡਾ. ਦੀਵਾਨ ਸਿੰਘ ਕਾਲੇਪਾਣੀ ਦੀ ਇਹ ਛੋਟੀ ਪ੍ਰਤੀਕਾਤਮਿਕ ਕਵਿਤਾ ਗਤੀ ਦੀ ਮਹਿਮਾ ਗਾਉਂਦੀ ਹੈ: ਵਗਦੇ ਪਾਣੀ, ਮਿਲਦੀਆਂ ਜਿੰਦਾਂ, ਉੱਡਦੀਆਂ ਰੂਹਾਂ ਅਤੇ ਤੁਰਦਾ ਮਨੁੱਖ ਹੀ ਜੀਵਨ ਹੈ।","nTerms":5},{"id":"kavita-taj-mahal","title":"ਤਾਜ ਮਹੱਲ (ਪ੍ਰੋ. ਮੋਹਨ ਸਿੰਘ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਪ੍ਰੋ. ਮੋਹਨ ਸਿੰਘ ਦੀ ਕਵਿਤਾ 'ਤਾਜ ਮਹੱਲ' ਪਹਿਲਾਂ ਚਾਨਣੀ ਰਾਤ ਵਿੱਚ ਇਸ ਸ਼ਾਨਦਾਰ ਇਮਾਰਤ ਦੀ ਸੁੰਦਰਤਾ ਦਾ ਚਿਤਰਣ ਕਰਦੀ ਹੈ ਅਤੇ ਫਿਰ ਇਸ ਦੀ ਉਸਾਰੀ ਵਿੱਚ ਲੱਗੇ ਮਜ਼ਦੂਰਾਂ ਦੇ ਸ਼ੋਸ਼ਣ ਦਾ ਦਰਦ ਬਿਆਨ ਕਰਦੀ ਹੈ।","nTerms":5},{"id":"kavita-chumm-chumm-rakho","title":"ਚੁੰਮ-ਚੁੰਮ ਰੱਖੋ (ਨੰਦ ਲਾਲ ਨੂਰਪੁਰੀ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਨੰਦ ਲਾਲ ਨੂਰਪੁਰੀ ਦੀ ਇਹ ਕਵਿਤਾ ਗੁਰੂ ਗੋਬਿੰਦ ਸਿੰਘ ਜੀ ਦੇ ਵੱਡੇ ਸਾਹਿਬਜ਼ਾਦਿਆਂ ਅਜੀਤ ਸਿੰਘ ਤੇ ਜੁਝਾਰ ਸਿੰਘ ਦੇ ਜੰਗ ਵਿੱਚ ਜਾਣ ਮਗਰੋਂ ਮਾਤਾ ਗੁਜਰੀ ਦੀ ਉਡੀਕ ਅਤੇ ਦੁੱਖ ਭਰੇ ਵਲਵਲਿਆਂ ਨੂੰ ਪ੍ਰਗਟ ਕਰਦੀ ਹੈ।","nTerms":5},{"id":"kavita-dosta","title":"ਦੋਸਤਾ (ਪਿਆਰਾ ਸਿੰਘ ਸਹਿਰਾਈ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਪਿਆਰਾ ਸਿੰਘ ਸਹਿਰਾਈ ਦੀ ਕਵਿਤਾ 'ਦੋਸਤਾ' ਮਨੁੱਖ ਨੂੰ ਸਮੇਂ ਦੀ ਨਜ਼ਾਕਤ ਪਛਾਣ ਕੇ ਹਿੰਮਤ ਨਾਲ ਅੱਗੇ ਵਧਣ, ਕਿਰਤ ਰਾਹੀਂ ਨਵਾਂ ਸੰਸਾਰ ਸਿਰਜਣ ਅਤੇ ਭਵਿੱਖ ਨੂੰ ਗਲਵੱਕੜੀ ਪਾਉਣ ਦੀ ਪ੍ਰੇਰਨਾ ਦਿੰਦੀ ਹੈ।","nTerms":5},{"id":"kavita-waris-shah","title":"ਵਾਰਸ ਸ਼ਾਹ (ਅੰਮ੍ਰਿਤਾ ਪ੍ਰੀਤਮ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਅੰਮ੍ਰਿਤਾ ਪ੍ਰੀਤਮ ਦੀ ਇਹ ਕਵਿਤਾ 1947 ਦੀ ਦੇਸ-ਵੰਡ ਦੇ ਦੁਖਾਂਤ ਨੂੰ ਪ੍ਰਗਟ ਕਰਦੀ ਹੈ ਅਤੇ ਹੀਰ ਦੇ ਕਿੱਸੇ ਦੇ ਰਚਣਹਾਰ ਵਾਰਸ ਸ਼ਾਹ ਨੂੰ ਕਬਰ ਵਿੱਚੋਂ ਬੋਲ ਕੇ ਪੰਜਾਬ ਦੇ ਦਰਦ ਦਾ ਨਵਾਂ ਵਰਕਾ ਲਿਖਣ ਲਈ ਪੁਕਾਰਦੀ ਹੈ।","nTerms":5},{"id":"kavita-mera-bachpan","title":"ਮੇਰਾ ਬਚਪਨ (ਹਰਿਭਜਨ ਸਿੰਘ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਡਾ. ਹਰਿਭਜਨ ਸਿੰਘ ਦੀ ਕਵਿਤਾ 'ਮੇਰਾ ਬਚਪਨ' ਇੱਕ ਅਜਿਹੇ ਬੱਚੇ ਦੀ ਵੇਦਨਾ ਹੈ ਜਿਸ ਦਾ ਪਿਤਾ ਨਹੀਂ ਰਿਹਾ, ਅਤੇ ਜਿਸ ਦੀ ਵਿਧਵਾ ਮਾਂ ਦੇ ਦੁੱਖ ਵਿੱਚ ਉਸ ਦਾ ਬਚਪਨ ਹੀ ਗੁਆਚ ਗਿਆ।","nTerms":5},{"id":"kavita-geet-shiv-kumar","title":"ਗੀਤ (ਸ਼ਿਵ ਕੁਮਾਰ ਬਟਾਲਵੀ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਸ਼ਿਵ ਕੁਮਾਰ ਬਟਾਲਵੀ ਦਾ 'ਗੀਤ' ਇੱਕ ਦੁੱਖ ਭਰਿਆ ਲੋਕ-ਗੀਤ ਹੈ ਜਿਸ ਵਿੱਚ ਪੀੜ ਨੂੰ ਪਰਾਗਾ (ਭੁੱਜਣ ਵਾਲਾ ਦਾਣਾ) ਬਣਾ ਕੇ ਭੱਠੀ ਵਾਲੀ ਕੋਲੋਂ ਭੁੰਨਾਉਣ ਦੇ ਬਿੰਬ ਰਾਹੀਂ ਬਿਰਹਾ ਅਤੇ ਉਦਾਸੀ ਪ੍ਰਗਟ ਕੀਤੀ ਗਈ ਹੈ।","nTerms":5},{"id":"kavita-aiven-na-butaan-te","title":"ਐਵੇਂ ਨਾ ਬੁੱਤਾਂ 'ਤੇ ਡੋਲ੍ਹੀ ਜਾ ਪਾਣੀ (ਸੁਰਜੀਤ ਪਾਤਰ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਸੁਰਜੀਤ ਪਾਤਰ ਦੀ ਇਹ ਗ਼ਜ਼ਲ ਪਾਣੀ ਦੇ ਬਿੰਬ ਰਾਹੀਂ ਸਮਝਾਉਂਦੀ ਹੈ ਕਿ ਸਾਧਨ ਬੇਜਾਨ ਬੁੱਤਾਂ ਦੀ ਥਾਂ ਜੀਵਤ ਰੁੱਖਾਂ ਅਤੇ ਪਿਆਸਿਆਂ ਲਈ ਵਰਤੇ ਜਾਣ, ਅਤੇ ਇਹ ਕੁਦਰਤੀ ਰੰਗਾਂ ਵਿੱਚ ਮਨੁੱਖੀ ਭਾਵਾਂ ਦਾ ਪ੍ਰਗਟਾਵਾ ਹੈ।","nTerms":5},{"id":"kahani-saanjh","title":"ਸਾਂਝ (ਸੁਜਾਨ ਸਿੰਘ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਸੁਜਾਨ ਸਿੰਘ ਦੀ ਕਹਾਣੀ 'ਸਾਂਝ' ਵਿੱਚ ਇੱਕ ਸਾਈਕਲ ਸਵਾਰ ਪ੍ਰੋਫ਼ੈਸਰ, ਲਾਲ ਚੀਰੇ ਵਾਲਾ ਪੇਂਡੂ ਸਾਈਕਲ-ਸਵਾਰ ਅਤੇ ਤਪਦੀ ਦੁਪਹਿਰ ਵਿੱਚ ਪੈਦਲ ਜਾਂਦੀ ਬੁੱਢੀ ਮਾਈ ਹਨ, ਅਤੇ ਹਮਦਰਦੀ ਰਾਹੀਂ ਦੋ ਅਣਜਾਣ ਮਨੁੱਖਾਂ ਵਿਚਕਾਰ ਸਾਂਝ ਬਣਦੀ ਹੈ।","nTerms":5},{"id":"kahani-neeli","title":"ਨੀਲੀ (ਕਰਤਾਰ ਸਿੰਘ ਦੁੱਗਲ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਕਰਤਾਰ ਸਿੰਘ ਦੁੱਗਲ ਦੀ ਕਹਾਣੀ 'ਨੀਲੀ' ਵਿੱਚ ਇੱਕ ਗਊ ਦੇ ਮਮਤਾ ਭਰੇ ਦੁੱਖ ਦਾ ਵਰਨਣ ਹੈ ਜਿਸ ਦੀ ਵੱਛੀ ਨੂੰ ਗਵਾਲੇ ਨੇ ਦੁੱਧ ਤੋਂ ਵਾਂਝਾ ਰੱਖ ਕੇ ਮਰਵਾ ਦਿੱਤਾ।","nTerms":5},{"id":"kahani-apna-des","title":"ਆਪਣਾ ਦੇਸ (ਸੰਤੋਖ ਸਿੰਘ ਧੀਰ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਸੰਤੋਖ ਸਿੰਘ ਧੀਰ ਦੀ ਕਹਾਣੀ 'ਆਪਣਾ ਦੇਸ' ਵਿੱਚ ਕੈਨੇਡਾ ਵਿੱਚ ਜੰਮੇ-ਪਲੇ ਦੋ ਭਰਾ ਭਾਰਤ ਆ ਕੇ ਇਸ ਨੂੰ ਓਪਰਾ ਮਹਿਸੂਸ ਕਰਦੇ ਹਨ, ਜਦਕਿ ਉਹਨਾਂ ਦਾ ਪਿਤਾ ਭਾਰਤ ਨੂੰ ਹੀ ਆਪਣਾ ਦੇਸ ਮੰਨਦਾ ਹੈ।","nTerms":5},{"id":"kahani-mada-banda","title":"ਮਾੜਾ ਬੰਦਾ (ਪ੍ਰੇਮ ਪ੍ਰਕਾਸ਼)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਪ੍ਰੇਮ ਪ੍ਰਕਾਸ਼ ਦੀ ਕਹਾਣੀ 'ਮਾੜਾ ਬੰਦਾ' ਇੱਕ ਮੱਧ-ਵਰਗੀ ਪਤੀ-ਪਤਨੀ ਅਤੇ ਇੱਕ ਗ਼ਰੀਬ ਰਿਕਸ਼ਾ-ਚਾਲਕ ਦੇ ਝਗੜੇ ਰਾਹੀਂ ਉਹਨਾਂ ਦੀ ਦੋਸ਼-ਭਾਵਨਾ, ਡਰ ਅਤੇ ਦਿਖਾਵੇ ਭਰੀ ਮਾਨਸਿਕਤਾ ਨੂੰ ਪ੍ਰਗਟ ਕਰਦੀ ਹੈ।","nTerms":5},{"id":"kahani-ghar-jah-apne","title":"ਘਰ ਜਾਹ ਆਪਣੇ (ਗੁਲਜ਼ਾਰ ਸਿੰਘ ਸੰਧੂ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਗੁਲਜ਼ਾਰ ਸਿੰਘ ਸੰਧੂ ਦੀ ਕਹਾਣੀ 'ਘਰ ਜਾਹ ਆਪਣੇ' ਵਿੱਚ ਜੀਤੋ ਦੇ ਵਿਆਹ ਅਤੇ ਵਿਦਾਇਗੀ ਦੇ ਮੌਕੇ ਉਸ ਦੇ ਸਖ਼ਤ ਦਿਸਦੇ ਵੀਰ ਦੇ ਅੰਦਰਲੇ ਨਰਮ ਤੇ ਭਾਵੁਕ ਮਨ ਅਤੇ ਭੈਣ-ਭਰਾ ਦੇ ਪਿਆਰ ਦਾ ਚਿਤਰਨ ਹੈ।","nTerms":5},{"id":"kahani-satiya-sei","title":"ਸਤੀਆ ਸੇਈ (ਦਲੀਪ ਕੌਰ ਟਿਵਾਣਾ)","section":"ਲਾਜ਼ਮੀ ਪੰਜਾਬੀ","summary":"ਡਾ. ਦਲੀਪ ਕੌਰ ਟਿਵਾਣਾ ਦੀ ਕਹਾਣੀ 'ਸਤੀਆ ਸੇਈ' ਵਿੱਚ ਲੇਖਿਕਾ ਰੇਲਗੱਡੀ ਵਿੱਚ ਇੱਕ ਮੰਗਤੇ ਦੇ ਗੀਤ ਤੋਂ ਪ੍ਰੇਰਿਤ ਹੋ ਕੇ ਭਗਤ ਸਿੰਘ ਦੀ ਮੰਗੇਤਰ ਨਾਲ ਕਲਪਿਤ ਮਿਲਣੀ ਰਾਹੀਂ ਉਸ ਦੇ ਵਿਛੋੜੇ, ਸਿਦਕ ਅਤੇ ਸਾਹਸ ਦਾ ਚਿਤਰਨ ਕਰਦੀ ਹੈ।","nTerms":5}]}});
